async (req, reply) => {
    // Rate-limit by IP — protect from a stuck agent in a loop.
    if (!canReport(req.ip)) {
      return reply.status(429).send({
        error: "rate_limited",
        message: `Too many agent reports from this IP. Limit ${REPORT_LIMIT}/hour.`,
        retry_after_seconds: Math.ceil(REPORT_WINDOW_MS / 1000),
      });
    }

    const v = validate(req.body);
    if (!v.ok) {
      return reply.status(400).send({
        error: "invalid_body",
        message: v.error,
        hint: "Provide at minimum `{summary: \"...\"}`. trace_id, detail, last_endpoint, last_error_code, agent_kind, and confused_about are optional.",
        docs: "/docs/AGENT_ONBOARDING_OBSERVABILITY.md#3-pcc_report-feedback-tool",
      });
    }

    const body = v.data;
    const report_id = `agr_${randomBytes(8).toString("hex")}`;

    // Prefer the trace_id surfaced by the trace-id middleware on the
    // request. The body's trace_id takes precedence when present (the
    // agent may know its own journey better than the request itself).
    const reqTraceId = (req as unknown as { traceId?: string }).traceId;
    const trace_id = body.trace_id ?? reqTraceId;

    return tracer.startActiveSpan(
      "pcc.feedback.agent_report",
      async (span) => {
        try {
          span.setAttribute("pcc.report_id", report_id);
          if (trace_id) span.setAttribute("pcc.trace_id", trace_id);
          if (body.agent_kind) span.setAttribute("pcc.agent_kind", body.agent_kind);
          if (body.last_endpoint) span.setAttribute("pcc.last_endpoint", body.last_endpoint);
          if (body.last_error_code) span.setAttribute("pcc.last_error_code", body.last_error_code);
          if (body.confused_about) span.setAttribute("pcc.confused_about", body.confused_about);

          // Persist to the audit log (temporary sink until piece 5 lands).
          auditService.log({
            eventType: "agent.report",
            actor: (req as unknown as { operatorId?: string; apiKeyId?: string }).operatorId
              ?? (req as unknown as { apiKeyId?: string }).apiKeyId
              ?? `anonymous:${req.ip}`,
            resourceType: "agent_report",
            resourceId: report_id,
            action: "create",
            metadata: {
              trace_id,
              summary: body.summary,
              detail: body.detail,
              last_endpoint: body.last_endpoint,
              last_error_code: body.last_error_code,
              agent_kind: body.agent_kind,
              confused_about: body.confused_about,
            },
            ip: req.ip,
            userAgent: req.headers["user-agent"],
          });

          // PostHog event for the live dashboard.
          trackServerEvent("agent_report_filed", {
            report_id,
            trace_id,
            agent_kind: body.agent_kind,
            last_error_code: body.last_error_code,
            confused_about: body.confused_about,
          });

          // Add a span event so any OTel collector subscribed to the
          // pcc.feedback.* namespace can stream it into the centralized
          // sink (piece 5).
          span.addEvent("agent_report_received", {
            "pcc.report_id": report_id,
            "pcc.trace_id": trace_id ?? "",
            "pcc.summary_length": body.summary.length,
          });

          return reply.status(201).send({
            ok: true,
            report_id,
            trace_id,
            message:
              "Thanks — your friction report has been recorded. Quote `trace_id` and `report_id` if you need to follow up.",
          });
        } finally {
          span.end();
        }
      },
    );
  }

async (req, reply) => {
      const { type, selections, assuranceTier, profileId, capabilityId } = req.body;
      const desc = getCapabilityDescriptor(type, capabilityId);

      if (desc.kind === "missing") {
        return sendMissing(reply, desc.reason);
      }

      let contract: BuilderContract;
      if (desc.kind === "template") {
        contract = builder.buildContract(
          type as CapabilityType,
          selections as Record<string, string | number | boolean | string[]>,
          assuranceTier as AssuranceTier,
          profileId,
        );
      } else {
        // Ad-hoc: synthesize a minimal BuilderContract from the
        // ResolvedBuildOptions view model.
        const pricingResult = pricing.calculate(
          desc.descriptor.resolved,
          selections,
        );
        // Validate against the synthesized view model so the quantity
        // required-check fires the same way it does for templates.
        const validationResult = validator.validate(
          desc.descriptor.resolved,
          selections,
          assuranceTier,
        );
        contract = {
          selections: selections as Record<string, string | number | boolean | string[]>,
          totalPrice: pricingResult.totalPrice.toFixed(2),
          priceBreakdown: pricingResult.breakdown,
          cwmStep: validationResult.cwmStep,
          validationErrors: validationResult.errors,
          isValid: validationResult.errors.length === 0,
          templateName: desc.descriptor.resolved.templateName,
          machineInfo: desc.descriptor.resolved.machineInfo,
        };
      }

      pipelineTelemetry.emit(
        "pipeline-" + Date.now(),
        "contract_build",
        "completed",
        {
          metadata: {
            endpoint: "/api/build/contract",
            type,
            assuranceTier,
            kind: desc.kind,
          },
        },
      );
      return { contract };
    }

async (req, reply) => {
      const { type, selections, profileId, capabilityId } = req.body;
      const desc = getCapabilityDescriptor(type, capabilityId);

      if (desc.kind === "missing") {
        return sendMissing(reply, desc.reason);
      }

      let result;
      if (desc.kind === "template") {
        result = builder.calculatePrice(
          type as CapabilityType,
          selections as Record<string, string | number | boolean | string[]>,
          profileId,
        );
      } else {
        // Ad-hoc: linear base * quantity.
        const quantity = Number((selections as Record<string, unknown>).quantity ?? 1) || 1;
        const basePriceNum = parseFloat(desc.descriptor.basePrice);
        const totalPrice = basePriceNum * quantity;
        result = {
          basePrice: basePriceNum,
          totalPrice,
          breakdown: [
            {
              paramKey: "quantity",
              paramLabel: "Quantity",
              selectedValue: String(quantity),
              impact: { mode: "per_unit", value: desc.descriptor.basePrice },
              amount: (basePriceNum * (quantity - 1)).toFixed(2),
            },
          ],
          currency: desc.descriptor.currency,
        };
      }

      pipelineTelemetry.emit(
        "pipeline-" + Date.now(),
        "quote_request",
        "completed",
        {
          metadata: {
            endpoint: "/api/build/price",
            type,
            kind: desc.kind,
          },
        },
      );
      return { pricing: result };
    }

async (req, reply) => {
      const { type, selections = {}, profileId, capabilityId } = req.body;
      const desc = getCapabilityDescriptor(type, capabilityId);

      if (desc.kind === "missing") {
        return sendMissing(reply, desc.reason);
      }

      let options;
      if (desc.kind === "template") {
        options = builder.getBuildOptions(
          type as CapabilityType,
          selections as Record<string, string | number | boolean | string[]>,
          profileId,
        );
      } else {
        // Ad-hoc: return the pre-built ResolvedBuildOptions view model.
        options = desc.descriptor.resolved;
      }

      pipelineTelemetry.emit(
        "pipeline-" + Date.now(),
        "quote_request",
        "completed",
        {
          metadata: {
            endpoint: "/api/build/options",
            type,
            kind: desc.kind,
          },
        },
      );
      return { options };
    }

async (req, reply) => {
      const parsed = StreamingBodySchema.safeParse(req.body);
      if (!parsed.success) {
        return reply.status(400).send({
          error: "invalid_body",
          message: "Invalid 3d-stream request body",
          details: parsed.error.flatten(),
        });
      }

      const {
        videoBytesBase64,
        mode,
        fps,
        maxFrames,
        downsamplePoints,
        modelPath,
        jobId,
        deviceId,
        expectedVideoHash,
      } = parsed.data;

      let videoBytes: Buffer;
      try {
        videoBytes = Buffer.from(videoBytesBase64, "base64");
      } catch (err) {
        return reply.status(400).send({
          error: "invalid_video_bytes",
          message: `videoBytesBase64 failed to decode: ${(err as Error).message}`,
        });
      }

      if (videoBytes.length === 0) {
        return reply.status(400).send({
          error: "empty_video",
          message: "Decoded video has zero bytes",
        });
      }
      if (videoBytes.length > MAX_VIDEO_BYTES) {
        return reply.status(413).send({
          error: "video_too_large",
          message: `Video exceeds ${MAX_VIDEO_BYTES} byte cap (got ${videoBytes.length})`,
        });
      }

      const actualHash =
        "sha256:" + crypto.createHash("sha256").update(videoBytes).digest("hex");
      if (expectedVideoHash && expectedVideoHash.toLowerCase() !== actualHash.toLowerCase()) {
        return reply.status(400).send({
          error: "video_hash_mismatch",
          message: `expectedVideoHash (${expectedVideoHash}) does not match sha256(videoBytes)=${actualHash}`,
        });
      }

      const tempPath = path.join(
        os.tmpdir(),
        `pcc-3d-stream-${process.pid}-${Date.now()}-${crypto.randomBytes(4).toString("hex")}.mp4`,
      );
      try {
        fs.writeFileSync(tempPath, videoBytes);
      } catch (err) {
        return reply.status(500).send({
          error: "tempfile_write_failed",
          message: (err as Error).message,
        });
      }

      try {
        const result = await runLingBotInference({
          videoPath: tempPath,
          mode,
          fps,
          maxFrames,
          downsamplePoints,
          modelPath,
          deviceId,
        });

        // Defense-in-depth: re-validate the returned trace against the spec
        // schema. The adapter already does this, but the gateway never trusts
        // a verifier result blindly.
        const guard = PointMap3DTraceSchemaExport.safeParse(result.trace);
        if (!guard.success) {
          return reply.status(500).send({
            error: "trace_schema_invalid",
            message: "Adapter returned a trace that failed schema validation",
            details: guard.error.flatten(),
          });
        }

        // Cross-check the trace's videoHash against what we computed —
        // catches an adapter bug where the trace was built from a different
        // file (race, leftover tempfile, etc.).
        if (result.trace.videoHash.toLowerCase() !== actualHash.toLowerCase()) {
          return reply.status(500).send({
            error: "trace_video_hash_mismatch",
            message: `trace.videoHash (${result.trace.videoHash}) does not match request video hash (${actualHash})`,
          });
        }

        pipelineTelemetry.emit(jobId ?? "capture-3d", "evidence_capture", "completed", {
          metadata: {
            subphase: "capture_3d_stream",
            jobId: jobId ?? null,
            frameCount: result.trace.frameCount,
            durationMs: result.durationMs,
            stubbed: result.stubbed,
            mode: result.trace.mode,
            model: result.trace.model,
          },
        });

        const response: StreamingResponse = {
          trace: result.trace,
          durationMs: result.durationMs,
          stubbed: result.stubbed,
          bytesReceived: videoBytes.length,
        };
        return response;
      } catch (err) {
        if (err instanceof LingBotAdapterError) {
          req.log.error({ err, code: err.code }, "capture_3d_stream adapter failed");
          pipelineTelemetry.emit(jobId ?? "capture-3d", "evidence_capture", "failed", {
            metadata: {
              subphase: "capture_3d_stream",
              jobId: jobId ?? null,
              error: err.code,
              message: err.message,
            },
            level: "error",
          });
          // Map adapter errors to user-actionable HTTP shapes.
          const status = err.code === "missing_video_path" ? 400 : 502;
          return reply.status(status).send({
            error: err.code,
            message: err.message,
            detail: err.detail,
          });
        }
        req.log.error({ err }, "capture_3d_stream threw");
        return reply.status(500).send({
          error: "internal_error",
          message: (err as Error).message,
        });
      } finally {
        try {
          fs.unlinkSync(tempPath);
        } catch {
          /* best-effort */
        }
      }
    }

async (req, reply) => {
      const parsed = SimBodySchema.safeParse(req.body);
      if (!parsed.success) {
        return reply.status(400).send({
          error: "invalid_body",
          message: "Invalid /api/capture/sim request body",
          details: parsed.error.flatten(),
        });
      }

      const {
        rolloutBytesBase64,
        fps,
        maxFrames,
        downsamplePoints,
        modelPath,
        jobId,
        deviceId,
        taskId,
        simulator,
        expectedRolloutHash,
      } = parsed.data;

      let artefactBytes: Buffer;
      try {
        artefactBytes = Buffer.from(rolloutBytesBase64, "base64");
      } catch (err) {
        return reply.status(400).send({
          error: "invalid_rollout_bytes",
          message: `rolloutBytesBase64 failed to decode: ${(err as Error).message}`,
        });
      }

      if (artefactBytes.length === 0) {
        return reply.status(400).send({
          error: "empty_rollout",
          message: "Decoded rollout artefact has zero bytes",
        });
      }
      if (artefactBytes.length > MAX_ARTEFACT_BYTES) {
        return reply.status(413).send({
          error: "rollout_too_large",
          message: `Rollout exceeds ${MAX_ARTEFACT_BYTES} byte cap (got ${artefactBytes.length})`,
        });
      }

      const actualHash =
        "sha256:" + crypto.createHash("sha256").update(artefactBytes).digest("hex");
      if (
        expectedRolloutHash &&
        expectedRolloutHash.toLowerCase() !== actualHash.toLowerCase()
      ) {
        return reply.status(400).send({
          error: "rollout_hash_mismatch",
          message: `expectedRolloutHash (${expectedRolloutHash}) does not match sha256(rolloutBytes)=${actualHash}`,
        });
      }

      const tempPath = path.join(
        os.tmpdir(),
        `pcc-sim-${process.pid}-${Date.now()}-${crypto.randomBytes(4).toString("hex")}.bin`,
      );
      try {
        fs.writeFileSync(tempPath, artefactBytes);
      } catch (err) {
        return reply.status(500).send({
          error: "tempfile_write_failed",
          message: (err as Error).message,
        });
      }

      try {
        const result = await runGenesisInference({
          artefactPath: tempPath,
          fps,
          maxFrames,
          downsamplePoints,
          modelPath,
          deviceId,
          taskId,
          simulator,
        });

        // Defense-in-depth: re-validate the returned trace against the spec
        // schema. The adapter already does this, but the gateway never trusts
        // its result blindly.
        const guard = SimulationTraceSchemaExport.safeParse(result.trace);
        if (!guard.success) {
          return reply.status(500).send({
            error: "trace_schema_invalid",
            message: "Adapter returned a trace that failed schema validation",
            details: guard.error.flatten(),
          });
        }

        // Cross-check the trace's rolloutHash against what we computed —
        // catches an adapter bug where the trace was built from a different
        // file (race, leftover tempfile, etc.).
        if (result.trace.rolloutHash.toLowerCase() !== actualHash.toLowerCase()) {
          return reply.status(500).send({
            error: "trace_rollout_hash_mismatch",
            message: `trace.rolloutHash (${result.trace.rolloutHash}) does not match request artefact hash (${actualHash})`,
          });
        }

        pipelineTelemetry.emit(jobId ?? "capture-sim", "evidence_capture", "completed", {
          metadata: {
            subphase: "capture_sim",
            jobId: jobId ?? null,
            frameCount: result.trace.frameCount,
            durationMs: result.durationMs,
            stubbed: result.stubbed,
            simulator: result.trace.scene.simulator,
            taskId: result.trace.scene.taskId,
            model: result.trace.model,
            adapterVersion: ADAPTER_VERSION,
          },
        });

        const response: SimResponse = {
          trace: result.trace,
          durationMs: result.durationMs,
          stubbed: result.stubbed,
          bytesReceived: artefactBytes.length,
        };
        return response;
      } catch (err) {
        if (err instanceof GenesisAdapterError) {
          req.log.error({ err, code: err.code }, "capture_sim adapter failed");
          pipelineTelemetry.emit(jobId ?? "capture-sim", "evidence_capture", "failed", {
            metadata: {
              subphase: "capture_sim",
              jobId: jobId ?? null,
              error: err.code,
              message: err.message,
            },
            level: "error",
          });
          // Map adapter errors to user-actionable HTTP shapes.
          const status = err.code === "missing_artefact_path" ? 400 : 502;
          return reply.status(status).send({
            error: err.code,
            message: err.message,
            detail: err.detail,
          });
        }
        req.log.error({ err }, "capture_sim threw");
        return reply.status(500).send({
          error: "internal_error",
          message: (err as Error).message,
        });
      } finally {
        safeUnlink(tempPath);
      }
    }

async (req, reply) => {
      const parsed = UploadBodySchema.safeParse(req.body);
      if (!parsed.success) {
        return reply.status(400).send({
          error: "invalid_body",
          message: "Invalid upload body",
          details: parsed.error.flatten(),
        });
      }

      const {
        manifest,
        captureBytesBase64,
        c2paManifestBase64,
        jobId,
        operatorId,
        challengeId,
        visualNonceEcho,
        submittedAt,
      } = parsed.data;

      // Decode the uploaded bytes once — all downstream gates need them.
      let captureBytes: Uint8Array;
      let c2paManifestBytes: Uint8Array | undefined;
      try {
        captureBytes = new Uint8Array(Buffer.from(captureBytesBase64, "base64"));
        if (c2paManifestBase64) {
          c2paManifestBytes = new Uint8Array(Buffer.from(c2paManifestBase64, "base64"));
        }
      } catch (err) {
        return reply.status(400).send({
          error: "invalid_bytes",
          message: "captureBytesBase64 failed to decode",
        });
      }

      // Verify operator-provided mediaHash matches the bytes we received
      // BEFORE handing to the verifier. This is the cheap pre-check — the
      // verifier's G1 will do the same, but we want a specific 400 here.
      const actualHash =
        "sha256:" + crypto.createHash("sha256").update(captureBytes).digest("hex");
      if (manifest.mediaHash.toLowerCase() !== actualHash.toLowerCase()) {
        return reply.status(400).send({
          error: "hash_mismatch",
          message:
            `manifest.mediaHash (${manifest.mediaHash}) does not match sha256(captureBytes)=${actualHash}`,
        });
      }

      // Resolve the CaptureNonceChallenge from cache if the client echoed
      // the id (required for G3 on CC1+). If the challenge isn't cached
      // the verifier G3 will fall through and fail for those classes.
      const challenge =
        challengeId && challengeCache.get(challengeId)
          ? challengeCache.get(challengeId)!
          : undefined;

      const verifier = getCaptureVerifier();
      let result: CaptureVerifierResult;
      try {
        result = await verifier.verify({
          manifest: manifest as CaptureManifest,
          captureBytes,
          c2paManifestBytes,
          challenge,
          visualNonceEcho,
          submittedAt,
          webAuthnPublicKey: undefined,
          webAuthnOrigin: undefined,
          webAuthnRpId: undefined,
          attestations: undefined,
        });
      } catch (err) {
        req.log.error({ err }, "capture_upload verifier threw");
        return reply.status(500).send({
          error: "verifier_threw",
          message: (err as Error).message,
        });
      }

      // Persist the verdict row.
      const verdictId = crypto.randomUUID();
      const row: VerdictRow = {
        id: verdictId,
        jobId: jobId ?? null,
        operatorId: operatorId ?? String(req.userId ?? "unknown"),
        captureHash: result.captureHash,
        manifestHash: result.manifestHash,
        declaredClass: captureClassOrdinal(result.declaredClass),
        verifiedClass: captureClassOrdinal(result.verifiedClass),
        verdict: result.verdict,
        gatesPassed: result.gatesPassed,
        gatesFailed: result.gatesFailed,
        warnings: result.warnings,
        anchorCandidate: result.anchorCandidate ? 1 : 0,
        resultJson: result as unknown as Record<string, unknown>,
        declaredClassStr: result.declaredClass,
        verifiedClassStr: result.verifiedClass,
        createdAt: new Date().toISOString(),
      };
      try {
        insertVerdict(row);
      } catch (err) {
        req.log.error({ err }, "capture_upload DB insert failed");
        return reply.status(500).send({
          error: "persist_failed",
          message: (err as Error).message,
        });
      }

      pipelineTelemetry.emit(jobId ?? verdictId, "evidence_capture", "completed", {
        metadata: {
          subphase: "capture_upload",
          verdictId,
          declaredClass: result.declaredClass,
          verifiedClass: result.verifiedClass,
          verdict: result.verdict,
          gatesPassed: result.gatesPassed,
          gatesFailed: result.gatesFailed,
          anchorCandidate: result.anchorCandidate,
        },
        level: result.verdict === "FAIL" ? "warn" : "info",
      });

      return {
        verdict: result.verdict,
        verifiedClass: result.verifiedClass,
        declaredClass: result.declaredClass,
        gatesPassed: result.gatesPassed,
        gatesFailed: result.gatesFailed,
        warnings: result.warnings,
        anchorCandidate: result.anchorCandidate,
        verdictId,
        captureHash: result.captureHash,
        manifestHash: result.manifestHash,
      };
    }

async (req, reply) => {
      const parsed = ListVerdictsQuerySchema.safeParse(req.query);
      if (!parsed.success) {
        return reply.status(400).send({
          error: "invalid_query",
          message: "Invalid query params",
          details: parsed.error.flatten(),
        });
      }
      const { jobId, limit } = parsed.data;
      const effectiveLimit = Math.min(limit ?? 50, 200);

      const { db } = getStore();
      const rows = jobId
        ? db
            .select()
            .from(captureVerdicts)
            .where(eq(captureVerdicts.jobId, jobId))
            .orderBy(desc(captureVerdicts.createdAt))
            .limit(effectiveLimit)
            .all()
        : db
            .select()
            .from(captureVerdicts)
            .orderBy(desc(captureVerdicts.createdAt))
            .limit(effectiveLimit)
            .all();

      pipelineTelemetry.emit(jobId ?? "capture-list", "evidence_capture", "completed", {
        metadata: {
          subphase: "list_verdicts",
          jobId: jobId ?? null,
          count: rows.length,
          limit: effectiveLimit,
        },
      });

      return {
        verdicts: rows.map((r) => ({
          id: r.id,
          jobId: r.jobId,
          operatorId: r.operatorId,
          captureHash: r.captureHash,
          manifestHash: r.manifestHash,
          declaredClass: r.declaredClassStr,
          verifiedClass: r.verifiedClassStr,
          verdict: r.verdict,
          gatesPassed: r.gatesPassed ?? [],
          gatesFailed: r.gatesFailed ?? [],
          warnings: r.warnings ?? [],
          anchorCandidate: r.anchorCandidate === 1,
          createdAt: r.createdAt,
        })),
        count: rows.length,
        limit: effectiveLimit,
        jobId: jobId ?? null,
      };
    }

async (req, reply) => {
      const parsed = ChallengeBodySchema.safeParse(req.body);
      if (!parsed.success) {
        return reply.status(400).send({
          error: "invalid_body",
          message: "Invalid challenge request body",
          details: parsed.error.flatten(),
        });
      }

      const { jobId, declaredClass, requestedTtlSeconds } = parsed.data;
      const ttl = Math.min(
        requestedTtlSeconds ?? CAPTURE_NONCE_MAX_AGE_SECONDS,
        CAPTURE_NONCE_MAX_AGE_SECONDS,
      );

      try {
        const chain = await getChainClient();
        const block = await chain.getLatestBlock();
        const svc = getChallengeService();
        const challenge = svc.issueCaptureNonce({
          issuedBy: String(req.userId ?? "unknown"),
          scope: `${jobId}:${declaredClass}`,
          visualNonceType: "qr",
          blockNumber: block.number,
          blockHash: block.hash,
          blockTimestamp: block.timestamp,
          chainId: chain.getChainId(),
          maxAgeSeconds: ttl,
        });

        // Cache the challenge so /upload can resolve it back to the full
        // server-side object. In-memory — challenges expire fast (≤120s).
        pruneChallengeCache();
        challengeCache.set(challenge.challengeId, challenge);

        // Work output root = sha256(scope) — deterministic so the client
        // can reconstruct it when assembling its capture manifest.
        const workOutputRoot = crypto
          .createHash("sha256")
          .update(challenge.scope)
          .digest("hex");

        const nonce = buildNonceFromChallenge(challenge, workOutputRoot);

        pipelineTelemetry.emit(jobId, "evidence_capture", "completed", {
          metadata: {
            subphase: "capture_challenge",
            challengeId: challenge.challengeId,
            declaredClass,
            ttl,
          },
        });

        const response: CaptureNonceChallengeResponse = {
          challengeId: challenge.challengeId,
          blockHash: challenge.blockHash,
          workOutputRoot,
          nonce,
          issuedAt: challenge.issuedAt,
          expiresAt: expiresAtIso(challenge),
          maxAgeSeconds: challenge.maxAgeSeconds,
          visualNonce: challenge.visualNonce,
          blockNumber: challenge.blockNumber,
          chainId: challenge.chainId,
          scope: challenge.scope,
        };
        return response;
      } catch (err) {
        req.log.error({ err }, "capture_challenge failed");
        return reply.status(500).send({
          error: "challenge_failed",
          message: (err as Error).message,
        });
      }
    }

async (req, reply) => {
      const parsed = AnchorBodySchema.safeParse(req.body);
      if (!parsed.success) {
        return reply.status(400).send({
          error: "invalid_body",
          message: "verdictId required",
          details: parsed.error.flatten(),
        });
      }
      const { verdictId } = parsed.data;

      const verdict = selectVerdict(verdictId);
      if (!verdict) {
        return reply.status(404).send({
          error: "verdict_not_found",
          message: `No verdict with id=${verdictId}`,
        });
      }

      // Gate A: only PASS verdicts with anchorCandidate:true are eligible.
      if (verdict.verdict !== "PASS") {
        return reply.status(400).send({
          error: "verdict_not_pass",
          message: `verdict ${verdict.verdict} not eligible for anchoring`,
          verdictId,
        });
      }
      if (!verdict.anchorCandidate) {
        return reply.status(400).send({
          error: "not_anchor_candidate",
          message: "verdict anchorCandidate=false — verifier declined anchoring",
          verdictId,
        });
      }

      // Deduplicate — one anchor per verdict.
      const existingAnchor = selectAnchor(verdictId);
      if (existingAnchor) {
        return {
          txHash: existingAnchor.txHash,
          blockNumber: existingAnchor.blockNumber,
          gasUsed: existingAnchor.gasUsed,
          anchoredAt: existingAnchor.anchoredAt,
          status: "already_anchored" as const,
        };
      }

      // Gate B: contract must be deployed. If not, return 202 deferred.
      const registryAddress = process.env.CAPTURE_REGISTRY_ADDRESS as
        | `0x${string}`
        | undefined;
      if (!registryAddress) {
        pipelineTelemetry.emit(
          verdict.jobId ?? verdictId,
          "evidence_capture",
          "skipped",
          {
            metadata: {
              subphase: "capture_anchor",
              verdictId,
              reason: "registry_not_deployed",
            },
            level: "warn",
          },
        );
        return reply.status(202).send({
          status: "deferred" as const,
          reason: "CaptureClassRegistry contract not deployed",
          verdictId,
        });
      }

      // Pull the original verifier result to reconstruct blockAnchor +
      // attestationsRoot. The result is stored as JSON (drizzle JSON mode),
      // so it comes back as an object already — no re-parse needed.
      const parsedResult = verdict.resultJson as unknown as
        | CaptureVerifierResult
        | undefined;

      const submittedBy = (req.userId ?? "0x0000000000000000000000000000000000000000") as
        `0x${string}`;

      // Extract the challenge's block anchor if present in the stored result.
      // Fall back to 0 if absent (CC0 captures without a challenge).
      const blockAnchor = 0; // challenge.blockNumber not surfaced in the result;
      // wire later once verifier persists it on the result.
      const capturedAt = BigInt(Math.floor(Date.now() / 1000));

      const attestationsRoot = (
        "0x" + "0".repeat(64)
      ) as `0x${string}`;
      const attesterCount = 0;

      try {
        const chain = await getChainClient();
        const tx = await chain.anchorCapture({
          registryAddress,
          anchor: {
            captureHash: toBytes32(verdict.captureHash),
            manifestHash: toBytes32(verdict.manifestHash),
            declaredClass: verdict.declaredClass,
            verifiedClass: verdict.verifiedClass,
            submittedBy,
            jobId: toBytes32(verdict.jobId ?? verdictId),
            challengeId: toBytes32(verdictId),
            blockAnchor,
            capturedAt,
            attestationsRoot,
            attesterCount,
          },
        });

        const anchoredAt = new Date().toISOString();
        insertAnchor({
          verdictId,
          txHash: tx.txHash,
          blockNumber: tx.blockNumber,
          gasUsed: tx.gasUsed,
          anchoredAt,
        });

        pipelineTelemetry.emit(
          verdict.jobId ?? verdictId,
          "evidence_capture",
          "completed",
          {
            metadata: {
              subphase: "capture_anchor",
              verdictId,
              txHash: tx.txHash,
              gasUsed: tx.gasUsed,
              blockNumber: tx.blockNumber,
            },
          },
        );

        return {
          txHash: tx.txHash,
          blockNumber: tx.blockNumber,
          gasUsed: tx.gasUsed,
          anchoredAt,
        };
      } catch (err) {
        req.log.error({ err }, "capture_anchor failed");
        pipelineTelemetry.emit(
          verdict.jobId ?? verdictId,
          "evidence_capture",
          "failed",
          {
            metadata: {
              subphase: "capture_anchor",
              verdictId,
              error: (err as Error).message,
            },
            level: "error",
          },
        );
        return reply.status(500).send({
          error: "anchor_failed",
          message: (err as Error).message,
        });
      }
    }

async (req, reply) => {
    const client = getEasyPostClient();
    if (!client.hasWebhookSecret) {
      return reply.code(503).send({
        error: "webhook_secret_not_configured",
        message: "Set EASYPOST_WEBHOOK_SECRET before pointing an EasyPost webhook at this endpoint.",
      });
    }

    const header = req.headers["x-hmac-signature"];
    const headerValue = Array.isArray(header) ? header[0] : header;
    const rawBody = req.rawBody ?? Buffer.alloc(0);
    if (!client.verifyWebhookSignature(rawBody, headerValue)) {
      req.log.warn({ hasHeader: !!headerValue, bytes: logSafeInt(rawBody.length) }, "carrier webhook: signature verification failed");
      return reply.code(401).send({ error: "invalid_signature" });
    }
    const signatureHeader = headerValue as string;

    const trackerEvent = client.parseTrackerEvent(req.body);
    if (!trackerEvent) {
      // Not a processable tracker event — 2xx so EasyPost does not retry forever.
      return reply.code(200).send({ received: true, ignored: true });
    }
    if (client.requireProductionMode && trackerEvent.providerMode !== "production") {
      // A sandbox tracker must never become evidence in production.
      req.log.warn({ trackingCode: logSafeId(trackerEvent.trackingCode), providerMode: logSafeId(trackerEvent.providerMode) }, "carrier webhook: non-production tracker refused");
      return reply.code(200).send({ received: true, ignored: true, reason: "provider_mode_not_production" });
    }

    const ledgered: LedgeredScan = { rawBodyB64: rawBody.toString("base64"), signatureHeader, parsed: trackerEvent };

    let result;
    try {
      result = await getCarrierShipmentStore().recordCarrierEvent(
        trackerEvent,
        (record, newStatus) => buildCarrierEvidenceEvent(record, newStatus, trackerEvent, rawBody, signatureHeader),
        ledgered,
        // Ledgering happens INSIDE the store's per-job/per-code lock (R4-2),
        // so a concurrent finalize cannot slip between decision and insert.
        { ledgerUnmatched: true },
      );
    } catch (err) {
      // Evidence gate or persistence failed: NOT marked seen, so the
      // provider's retry gets a clean attempt. Non-2xx makes EasyPost retry.
      req.log.error({ code: "carrier_webhook_apply_failed", errorClass: knownErrorClassName(err), trackingCode: logSafeId(trackerEvent.trackingCode) }, "carrier webhook: failed to apply event");
      return reply.code(500).send({ error: "apply_failed" });
    }

    if (!result.ok) {
      switch (result.reason) {
        case "unknown_tracking_code":
        case "not_finalized":
          // OURS-maybe but not yet matchable: already durably ledgered by the
          // store (R3-5), under its lock (R4-2). 2xx — we hold it now.
          req.log.info({ trackingCode: logSafeId(trackerEvent.trackingCode), reason: logSafeId(result.reason), ledgered: result.ledgered === true }, "carrier webhook: ledgered for post-finalize replay");
          return reply.code(200).send({ received: true, pending: true, reason: result.reason });
        case "scan_predates_commitment":
          // Permanently non-qualifying (R3-4): the commitment did not predate
          // this scan, so it can never support the pre-commitment claim.
          req.log.warn({ trackingCode: logSafeId(trackerEvent.trackingCode) }, "carrier webhook: scan predates commitment — permanently non-qualifying");
          return reply.code(200).send({ received: true, matched: false, reason: result.reason });
        default:
          // tracker_missing / tracker_mismatch / shipment_mismatch: same
          // code, different purchase identity — refuse, warn.
          req.log.warn({ trackingCode: logSafeId(trackerEvent.trackingCode), reason: logSafeId(result.reason) }, "carrier webhook: identity refused");
          return reply.code(200).send({ received: true, matched: false, reason: result.reason });
      }
    }

    return reply.code(200).send({
      received: true,
      matched: true,
      jobId: result.record.jobId,
      status: result.newStatus,
      outcome: result.outcome,
    });
  }

