      resourceId: registration.id,
      action: "create",
      metadata: { name: registration.name, category: registration.category },
      ip: req.ip,
      userAgent: req.headers["user-agent"],
    });
    return { status: "ok", registration };
  }

async (req, reply) => {
    return Sentry.startSpan(
      { name: "onboard.prove", op: "onboard", attributes: { "registration.id": req.params.id } },
      async () => {
        const repos = getRepos();
        const reg = repos.registrations.findById(req.params.id);
        if (!reg) return reply.status(404).send({ error: "not_found" });

        // Verify the caller owns this registration (prevents self-approval by other operators)
        const callerId = (req as any).operatorId ?? (req as any).userId;
        const regOperator = (reg as any).operator?.walletAddress
          ?? (reg as any).operator?.email
          ?? (reg as any).walletAddress
          ?? (reg as any).email
          ?? (reg as any).operatorId;
        if (callerId && regOperator && callerId !== regOperator) {
          return reply.status(403).send({ error: "forbidden", message: "You can only prove your own registration" });
        }

        if (reg.status === "active") {
          return reply.status(400).send({ error: "already_active", message: "Registration is already active" });
        }
        if (reg.status === "rejected") {
          return reply.status(400).send({ error: "rejected", message: "Registration was rejected — submit a new one" });
        }

        const body = req.body as {
          evidence?: {
            /** SHA-256 bundle hash of the evidence */
            bundleHash?: string;
            /** Evidence events from the test job */
            events?: Array<{
              type: string;
              timestamp: string;
              payload: Record<string, unknown>;
            }>;
            /** Base64-encoded photo of test output (e.g. printed page, machined part) */
            photoBase64?: string;
            /** Device health snapshot */
            deviceHealth?: {
              status: string;
              firmware?: string;
              model?: string;
              uptime?: number;
              [key: string]: unknown;
            };
            /** IPFS CID if evidence was already uploaded */
            ipfsCid?: string;
          };
        } | undefined;

        const evidence = body?.evidence;
        if (!evidence) {
          return reply.status(400).send({
            error: "evidence_required",
            message: "Submit evidence to prove your device works. Include at least one of: bundleHash + events, photoBase64, or deviceHealth.",
            example: {
              evidence: {
                bundleHash: "sha256:abc123...",
                events: [
                  { type: "execution_completed", timestamp: new Date().toISOString(), payload: { jobType: "test", pagesCount: 1 } },
                  { type: "camera_snapshot", timestamp: new Date().toISOString(), payload: { description: "Photo of printed test page" } },
                ],
                deviceHealth: { status: "idle", model: "HP OfficeJet Pro 9010", firmware: "2409A" },
              },
            },
          });
        }

        // ── Validate bundleHash format ────────────────────────────────────
        if (evidence.bundleHash !== undefined) {
          if (!evidence.bundleHash.startsWith("sha256:") || evidence.bundleHash.length < 40) {
            return reply.status(400).send({
              error: "invalid_bundle_hash",
              message: "bundleHash must start with 'sha256:' and be at least 40 characters (e.g. sha256:abc123...).",
            });
          }
        }

        // ── Validate event timestamps ─────────────────────────────────────
        if (evidence.events && evidence.events.length > 0) {
          const now = Date.now();
          const oneHourMs = 60 * 60 * 1000;
          for (const ev of evidence.events) {
            const ts = Date.parse(ev.timestamp);
            if (isNaN(ts)) {
              return reply.status(400).send({
                error: "invalid_event_timestamp",
                message: `Event of type "${ev.type}" has an invalid ISO timestamp: "${ev.timestamp}"`,
              });
            }
            if (ts > now + 5000) {
              return reply.status(400).send({
                error: "future_event_timestamp",
                message: `Event of type "${ev.type}" has a timestamp in the future: "${ev.timestamp}"`,
              });
            }
            if (now - ts > oneHourMs) {
              return reply.status(400).send({
                error: "stale_event_timestamp",
                message: `Event of type "${ev.type}" is older than 1 hour: "${ev.timestamp}". Submit fresh evidence.`,
              });
            }
          }
        }

        // Validate evidence — need at least one substantial proof
        const proofs: string[] = [];
        const warnings: string[] = [];

        // 1. Evidence bundle with events
        if (evidence.bundleHash && evidence.events && evidence.events.length > 0) {
          const hasCompletion = evidence.events.some((e) =>
            ["execution_completed", "camera_snapshot", "power_profile_summary"].includes(e.type),
          );
          if (hasCompletion) {
            proofs.push(`evidence_bundle: ${evidence.events.length} events, hash=${evidence.bundleHash.slice(0, 20)}...`);
          } else {
            warnings.push("Evidence events present but no completion/snapshot event found");
          }
        }

        // 2. Photo of test output
        if (evidence.photoBase64) {
          const sizeBytes = Math.ceil((evidence.photoBase64.length * 3) / 4);
          if (sizeBytes > 1024) {
            proofs.push(`photo: ${(sizeBytes / 1024).toFixed(0)}KB image`);
          } else {
            warnings.push("Photo too small to be meaningful (< 1KB)");
          }
        }

        // 3. Device health check
        if (evidence.deviceHealth) {
          if (evidence.deviceHealth.status && evidence.deviceHealth.model) {
            proofs.push(`device_health: ${evidence.deviceHealth.model} status=${evidence.deviceHealth.status}`);
          } else {
            warnings.push("Device health missing status or model");
          }
        }

        // 4. IPFS CID (evidence already uploaded to decentralized storage)
        if (evidence.ipfsCid) {
          proofs.push(`ipfs: ${evidence.ipfsCid}`);
        }

        if (proofs.length === 0) {
          return reply.status(422).send({
            error: "insufficient_evidence",
            message: "Evidence did not meet minimum requirements for auto-approval.",
            warnings,
            hint: "Provide a bundleHash with completion events, a photo of test output, or a device health snapshot with model and status.",
          });
        }

        // ── Determine assurance tier ────────────────────────────────────────
        const hasEvents = evidence.events && evidence.events.length > 0;
        const hasCompletion = hasEvents && evidence.events!.some((e) =>
          ["execution_completed", "camera_snapshot", "power_profile_summary"].includes(e.type),
        );
        const hasPhoto = !!(evidence.photoBase64 && Math.ceil((evidence.photoBase64.length * 3) / 4) > 1024);
        const hasDeviceHealth = !!(evidence.deviceHealth?.status && evidence.deviceHealth?.model);
        const hasBundleHash = !!(evidence.bundleHash);

        let assuranceTier: 0 | 1 | 2;
        let tierWarning: string | undefined;

        if (hasPhoto && hasDeviceHealth && hasEvents) {
          // Tier 2: photo + device health + events
          assuranceTier = 2;
        } else if (hasBundleHash && hasEvents && hasCompletion) {
          // Tier 1: bundle hash + events with completion event
          assuranceTier = 1;
        } else {
          // Tier 0: self-attested only (deviceHealth only, no events or photo)
          assuranceTier = 0;
          tierWarning = "Self-attested only — no independent verification";
        }

        // Evidence passes — auto-approve and activate (PERSISTENT — survives deploys)
        const now = new Date().toISOString();
        const proveMetadata = JSON.stringify({ provedAt: now, autoApproved: true, proofs, evidenceBundleHash: evidence.bundleHash ?? null, evidenceIpfsCid: evidence.ipfsCid ?? null, assuranceTier });
        repos.registrations.updateStatus(req.params.id, "active", { approvedAt: now, description: `PROVED: ${proveMetadata}` });

        pipelineTelemetry.emit(reg.id, "operator_verify", "completed", { metadata: { proofCount: proofs.length, autoApproved: true, assuranceTier } });
        trackServerEvent("operator_proved", { proofCount: proofs.length, assuranceTier });
        auditService.log({
          eventType: "operator.proved",
          actor: (req as any).operatorId ?? (req as any).apiKeyId ?? reg.operator?.walletAddress,
          resourceType: "registration",
          resourceId: reg.id,
          action: "prove",
          metadata: { proofCount: proofs.length, assuranceTier, autoApproved: true, proofs },
          ip: req.ip,
          userAgent: req.headers["user-agent"],
        });
        return {
          registration: { ...reg, status: "active", approvedAt: now },
          autoApproved: true,
          activated: true,
          proofs,
          assuranceTier,
          warning: tierWarning,
          warnings: warnings.length > 0 ? warnings : undefined,
          message: "Evidence accepted — registration auto-approved and activated. Your device is now live on the network.",
        };
      },
    );
  }

async (req, reply) => {
    const text = coalesceAnalysisText(req.body);
    if (!text) {
      return reply.status(400).send({
        error: "text_required",
        message:
          "Provide the operator or machine description to analyze. Send { text } " +
          "(also accepts description / content / documentText / documents[]).",
      });
    }

    try {
      const sourceDocumentId = coalesceSourceDocumentId(req.body);
      const { analysis, mode, warning } = await analyzeOnboardingText(text, { sourceDocumentId });
      trackServerEvent("document_analyzed", {
        mode,
        type: analysis.suggestedCapabilities[0]?.type ?? "unknown",
      });
      return { status: "ok", analysis, mode, ...(warning ? { warning } : {}) };
    } catch (e) {
      req.log.error(e, "[onboard] analyze failed");
      return reply.status(500).send({
        error: "analysis_failed",
        message: (e as Error).message,
      });
    }
  }

async (req, reply) => {
    const { jobId, kernelId, evidence, timestamp } = req.body ?? {};

    if (!isNonEmptyId(jobId)) {
      return reply.code(400).send({ error: "jobId required" });
    }
    if (kernelId !== undefined && !isNonEmptyId(kernelId)) {
      return reply.code(400).send({ error: "kernelId must be a non-empty string" });
    }
    if (!evidence) {
      return reply.code(400).send({ error: "evidence required" });
    }
    if (isAnonymous(authorityOf(req))) return reply.code(401).send(AUTHENTICATION_REQUIRED);

    try {
      const repos = getRepos();

      // Verify the job exists
      const job = repos.jobs.findById(jobId);
      if (!job) {
        // Return 200 anyway — the node shouldn't hard-fail on this
        app.log.warn(`operator-relay: evidence for unknown job ${jobId}`);
        return {
          stored: false,
          jobId,
          warning: "job_not_found",
          timestamp: new Date().toISOString(),
        };
      }

      // Evidence takes decide, per DECISIONS 2026-10-04 01:25 (N31c).
      const refusal = refuseKernelRequest(req, job.kernelId, "decide");
      if (refusal) return reply.code(refusal.status).send(refusal.body);

      // The stored bundle belongs to the job's kernel. A body naming another kernel is
      // refused, never stored under it (N80: stored evidence tells the truth).
      if (kernelId !== undefined && job.kernelId && kernelId !== job.kernelId) {
        return reply.code(409).send({
          error: "kernel_mismatch",
          message: `evidence names kernel ${kernelId}, but job ${jobId} belongs to kernel ${job.kernelId}`,
        });
      }

      // Store evidence bundle
      const bundleId = `ev-${uuidv4()}`;
      const now = new Date().toISOString();

      // SEAM-2 (path 1): capture the node's REAL device (#236) Ed25519 signature and
      // real bundleHash when the pushed evidence carries a signed bundle — instead of
      // discarding the signature and writing a gateway placeholder. This only
      // PERSISTS the truth of what the device signed; it does NOT verify it or gate
      // settlement. The oracle #52 verifier (stubbed, fail-closed) still owns whether
      // this evidence may settle. Evidence without a device signature keeps the
      // placeholder SIGNATURE (a gateway placeholder, never device-signed).
      //
      // The stored bundleHash is never made up (N80, rehearsal R0 G3). It used to be
      // `sha256-<bundleId>` for any unsigned body, with no events stored, so it committed
      // to nothing that was received. commitRelayEvidence recomputes LO-EV event hashes, or
      // the hash of a device-signed document that names THIS job and its kernel (adk #4322),
      // and refuses everything else: a supplied hash its content does not reproduce, a
      // document signed for another job or kernel (409), a bare device digest that names no
      // job, an ambiguous envelope, malformed events, and a document the gateway could not
      // keep (cross-family review E4).
      //
      // assuranceTier stays 0 ON PURPOSE (fails closed): an UNVERIFIED bundle
      // "actually supports" only the tier-0 permissionless floor (eligibility.ts).
      // The node's self-declared tier is a claim, not proof — trusting it here would
      // let resume-settlement's `?? latestBundle.assuranceTier` fallback escalate the
      // release tier from unverified evidence. The tier is lifted only once the gated
      // #52 verifier confirms the evidence on deployed infra (SEAM-2 ready-but-gated).
      const captured = extractNodeSignedBundle(evidence);
      // The job context comes from the job row, never from the evidence.
      const committed = await commitRelayEvidence(evidence, captured, { jobId: job.id, kernelId: job.kernelId ?? null });
      if (!committed.ok) {
        const conflict = committed.refusal.error === "job_mismatch" || committed.refusal.error === "kernel_mismatch";
        return reply.code(conflict ? 409 : 422).send({ ...committed.refusal, stored: false, jobId });
      }
      const { bundleHash, hashModel, events } = committed.commitment;
      const kernelSignature = captured
        ? captured.kernelSignature
        : {
            signer: job.kernelId ?? "unknown",
            algorithm: "sha256",
            value: "operator-relay-auto",
          };

      try {
        // One transaction (cross-family review E4, finding 2): the bundle and its events
        // commit together or not at all, so a failed event insert never leaves a stored
        // bundle whose hash its missing events cannot reproduce.
        getStore().db.transaction(() => {
          repos.evidence.insert({
            id: bundleId,
            jobId,
            stepId: job.stepId ?? "operator-relay",
            kernelId: job.kernelId,
            assuranceTier: 0,
            bundleHash,
            kernelSignature,
            sessionKeyAuthorization: captured?.sessionKeyAuthorization ?? null,
            createdAt: now,
          });
          if (events.length > 0) {
            repos.evidence.insertEvents(
              events.map((ev, i) => ({
                id: `${bundleId}:${i}`,
                bundleId,
                type: ev.type,
                timestamp: ev.timestamp,
                source: ev.source as { deviceId: string; deviceType: string; kernelId: string },
                payload: ev.payload,
                hash: ev.hash,
              })),
            );
          }
        });
      } catch (insertErr) {
        // Evidence insert failed — still acknowledge receipt
        app.log.error(`operator-relay: evidence insert failed: ${insertErr}`);
        return {
          stored: false,
          jobId,
          bundleId,
          error: "storage_failed",
          timestamp: now,
        };
      }

      return {
        stored: true,
        jobId,
        bundleId,
        // What was committed: the stored hash, how it was made, and how many LO-EV
        // events were stored with it (0 when the body carried none in that form).
        contentHash: bundleHash,
        hashModel,
        eventsStored: events.length,
        // True when the node's real device-signed (#236) bundle was captured
        // (real Ed25519 signature persisted); false when the placeholder was used.
        deviceSigned: !!captured,
        // Nothing here verifies a signature: capture persists it, and the gated #52
        // verifier owns verification.
        signatureVerified: false,
        timestamp: now,
      };
    } catch (err) {
      return reply.code(500).send({
        error: "evidence_store_failed",
        message: err instanceof Error ? err.message : "Unknown error",
      });
    }
  }

async (req, reply) => {
    const query = req.query as { kernelId?: unknown; status?: unknown };
    // A repeated parameter arrives as a list: a client error (400), not a failed read (503).
    for (const [name, value] of [["kernelId", query.kernelId], ["status", query.status]] as const) {
      if (value !== undefined && typeof value !== "string") {
        return reply.code(400).send({ error: "invalid_query", message: `${name} must be given once, as a single value.` });
      }
      // An empty or whitespace-only filter is a client error, not an absent filter:
      // treating it as "no filter" would silently broaden the query past what the caller
      // asked for.
      if (typeof value === "string" && value.trim() === "") {
        return reply.code(400).send({ error: "invalid_query", message: `${name} must not be empty.` });
      }
    }
    const kernelId = query.kernelId as string | undefined;
    const status = query.status as string | undefined;

    try {
      const { db } = getStore();
      let rows;

      if (kernelId && status) {
        rows = db.select().from(pendingApprovals)
          .where(and(eq(pendingApprovals.kernelId, kernelId), eq(pendingApprovals.status, status)))
          .all();
      } else if (kernelId) {
        rows = db.select().from(pendingApprovals)
          .where(eq(pendingApprovals.kernelId, kernelId))
          .all();
      } else if (status) {
        rows = db.select().from(pendingApprovals)
          .where(eq(pendingApprovals.status, status))
          .all();
      } else {
        rows = db.select().from(pendingApprovals).all();
      }

      return { approvals: rows };
    } catch (err) {
      // A failed read is not "no approvals": an empty list here would hide recorded
      // approvals during an outage. Same refusal as the operator policy read above.
      req.log.warn({ kernelId, status, err }, "operator approvals read failed");
      return reply.code(503).send({ error: "read_failed", message: "The approvals could not be read. Try again shortly." });
    }
  }

async (req, reply) => {
      let row;
      try {
        const { db } = getStore();
        row = db.select().from(operatorPolicies)
          .where(eq(operatorPolicies.kernelId, req.params.kernelId))
          .get();
      } catch (err) {
        // A failed read is not "no policy set": answering the default here would show
        // an operator's real guardrails as the defaults.
        req.log.warn({ kernelId: req.params.kernelId, err }, "operator policy read failed");
        return reply.code(503).send({ error: "read_failed", message: "The operator policy could not be read. Try again shortly." });
      }
      if (!row) {
        return { policy: DEFAULT_OPERATOR_POLICY, source: "default" };
      }
      return { policy: row.policy, updatedAt: row.updatedAt };
    }

async (req, reply) => {
    const { jobId } = req.params;
    const body = (req.body ?? {}) as Record<string, unknown>;
    // Set once we've won the completion claim below, so a failure before
    // evidence is durably recorded can release the claim (see the catch).
    let claimedOriginalStatus: string | undefined;

    try {
      const repos = getRepos();
      const { db } = getStore();

      // Look up the job
      const job = repos.jobs.findById(jobId);
      if (!job) {
        return reply.status(404).send({ error: "Job not found" });
      }

      // Atomic completion claim (P1). better-sqlite3 is synchronous, so this
      // UPDATE ... WHERE ... RETURNING runs to completion without yielding the
      // event loop — only ONE caller can flip a job into 'completing'. Closes
      // two holes at once:
      //   (a) re-runnability — the old guard rejected only settled/completed,
      //       so a retried PUT on an 'evidence_submitted' job rebuilt the
      //       evidence bundle and re-ran settlement;
      //   (b) the check-then-act race — the old read happened many awaits
      //       before the terminal write, so two concurrent PUTs both passed
      //       and double-settled.
      const claimed = db
        .update(schema.jobs)
        .set({ status: "completing" })
        .where(
          and(
            eq(schema.jobs.id, jobId),
            sql`${schema.jobs.status} NOT IN ('completing','evidence_submitted','settled','completed','cancelled','failed')`,
          ),
        )
        .returning()
        .all();
      if (claimed.length !== 1) {
        // Lost the claim: the job is terminal, already has evidence submitted,
        // or another completion is in flight. Reject rather than double-run.
        return reply.status(409).send({
          error: "Job already completed or completion in progress",
          status: job.status,
        });
      }
      claimedOriginalStatus = job.status;

      // #3 — the REAL assurance tier this job was negotiated at. N3 now writes
      // this tier on-chain as the milestone's requiredTier, so the evidence
      // bundle, the oracle verification, and the EAS attestation must all attest
      // at the SAME tier — otherwise a tier>=1 milestone can't be released via
      // this route (funds stranded), the N3 failure mode resurfacing through a
      // different door. Source of truth is the session's contractTerms (what
      // createJobFromSession bound on-chain); the jobs table has no tier column.
      const tierSessionRow = db
        .select()
        .from(negotiationSessions)
        .where(eq(negotiationSessions.jobId, jobId))
        .get();
      const jobAssuranceTier = toTier(
        (tierSessionRow?.contractTerms as Record<string, unknown> | null)?.assuranceTier ?? 0,
      );

      // ── 1. Gather evidence ─────────────────────────────────────────
      // Collect tool call results from the scope's audit trail
      const scopes = db.select().from(executionScopes)
        .where(eq(executionScopes.jobId, jobId))
        .all();

      const auditTrail: Array<Record<string, unknown>> = [];
      for (const scope of scopes) {
        const calls = db.select().from(toolCallRelay)
          .where(eq(toolCallRelay.scopeId, scope.id))
          .all();
        for (const call of calls) {
          auditTrail.push({
            toolName: call.toolName,
            args: call.toolArgs,
            status: call.status,
            result: call.result,
            createdAt: call.createdAt,
            completedAt: call.completedAt,
          });
        }
      }

      const now = new Date().toISOString();
      const bundleId = `bundle-${crypto.randomUUID().slice(0, 12)}`;

      // Digest of the tool-call audit trail. The old code hashed an ad-hoc
      // {jobId, auditTrail, ...} JSON into bundleHash and then DISCARDED those
      // bytes — the committed hash had no retrievable preimage, so the
      // verification oracle (which fetches GET /api/evidence/:hash and
      // re-hashes the raw bytes, failing closed) could never verify a Path-B
      // bundle. The audit-trail binding now rides INSIDE the served envelope
      // (execution_completed payload below) instead of being the whole
      // preimage.
      const auditTrailSha256 = crypto
        .createHash("sha256")
        .update(JSON.stringify(auditTrail))
        .digest("hex");

      // Build evidence events
      const customEvents = (body.evidenceEvents ?? []) as Array<{
        type: string;
        payload?: Record<string, unknown>;
      }>;

      const events = [
        {
          id: `ev-${crypto.randomUUID().slice(0, 8)}`,
          type: "execution_completed",
          timestamp: now,
          source: {
            deviceId: "gateway",
            deviceType: "controller",
            kernelId: job.kernelId,
          },
          payload: {
            toolCallCount: auditTrail.length,
            completedAt: now,
            // Binds the audit trail (and the caller's own evidence hash, when
            // supplied) inside the hashed envelope — see bundleHash below.
            auditTrailSha256,
            ...(body.evidenceHash ? { customEvidenceHash: body.evidenceHash } : {}),
          } as Record<string, unknown>,
          hash: `sha256:${crypto.createHash("sha256").update(JSON.stringify({ type: "execution_completed", timestamp: now })).digest("hex")}`,
        },
        ...customEvents.map((ev) => ({
          id: `ev-${crypto.randomUUID().slice(0, 8)}`,
          type: ev.type,
          timestamp: now,
          source: {
            deviceId: "gateway",
            deviceType: "controller",
            kernelId: job.kernelId,
          },
          payload: ev.payload ?? {},
          hash: `sha256:${crypto.createHash("sha256").update(JSON.stringify(ev)).digest("hex")}`,
        })),
      ];

      const kernelSignature = {
        signer: "0x0000000000000000000000000000000000000000" as const,
        algorithm: "ed25519" as const,
        value: "gateway-auto-sign",
      };

      // Commit bundleHash over the CANONICAL ENVELOPE — the exact bytes
      // GET /api/evidence/:hash serves back. The oracle's fetch-and-verify
      // (re-hash raw bytes, fail closed) and its authenticity-of-origin floor
      // (reads events[] off the hash-verified doc, pcc-oracle PR #15) both
      // work against these bytes; a re-serialization that dropped
      // source.simulated / payload.mock would break the hash. NOTE: these
      // gateway-synth events are DERIVED from the real tool-call audit trail
      // (digital execution records), not simulations — so they are not tagged
      // source.simulated; their honest tell is the zero-address signer, which
      // ALCOA "Original" and the oracle's identity check both catch.
      const envelopeCanonical = buildCanonicalEvidenceEnvelope(
        {
          id: bundleId,
          jobId,
          stepId: job.stepId,
          kernelId: job.kernelId,
          assuranceTier: jobAssuranceTier,
          createdAt: now,
          kernelSignature,
        },
        events,
      );
      const gatewayBundleHash = `sha256:${crypto.createHash("sha256").update(envelopeCanonical).digest("hex")}`;

      // ── SEAM-2 (path 2): choose the settlement anchor. READY BUT GATED. ──
      // By DEFAULT the gate is CLOSED — the #52 machine.execution_log verifier is
      // stubbed/fail-closed AND the SEAM2_DEVICE_EVIDENCE_SETTLEMENT flag is unset —
      // so `resolveSettlementEvidence` returns the gateway fallback: `settlementSignature`
      // is the gateway placeholder and `bundleHash` is the canonical-envelope hash above
      // (serve-the-flag) — the default money path is unchanged apart from the now
      // oracle-verifiable hash. When a real device has cleared #52 on deployed infra and
      // the gate is opened (NOT done here), a device-signed (#236) bundle captured by
      // operator-relay (path 1) anchors settlement on the DEVICE's own hash + signature
      // instead of this placeholder, but only when its signed bundleHash opens to the
      // stored events, those events commit THIS job and the kernel that accepted it
      // (LO-EV-9), and its Ed25519 signature verifies against that kernel's REGISTERED
      // signer. Fails closed to the gateway anchor on any failure — the money path
      // never weakens.
      const gatewaySignature: StoredSignature = {
        signer: "0x0000000000000000000000000000000000000000",
        algorithm: "ed25519",
        value: "gateway-auto-sign",
      };
      const seam2GateOpen = deviceEvidenceSettlementEnabled();
      let seam2DeviceBundles: SettlementEvidenceSlot[] = [];
      let seam2RegisteredSigner: unknown = null;
      if (seam2GateOpen) {
        // Extra lookups only when the gate is open — the closed path is unchanged.
        // Every device-signed row is a candidate: the relay accepts any number of
        // rows per job, so the first row is not necessarily the genuine one.
        seam2DeviceBundles = repos.evidence
          .findByJob(jobId)
          .filter((r) => isDeviceSignedSignature(r.kernelSignature as StoredSignature))
          .map((r) => ({
            bundleHash: r.bundleHash,
            kernelSignature: r.kernelSignature as StoredSignature,
            assuranceTier: r.assuranceTier,
            ...(r.sessionKeyAuthorization
              ? { sessionKeyAuthorization: r.sessionKeyAuthorization }
              : {}),
            contractId: jobId,
            bundleId: r.id,
            events: repos.evidence.findEventsByBundle(r.id).map((ev) => ({
              id: ev.id,
              type: ev.type,
              timestamp: ev.timestamp,
              source: ev.source,
              payload: ev.payload,
              hash: ev.hash,
            })),
            // No settlement unit or challenge: this route drives milestone 0 of the job's
            // per-job escrow, which has no unit id. LO-EV-9 then refuses evidence that commits
            // either (E11 F1), so evidence signed for a V-next milestone cannot anchor it.
            subject: { jobId, kernelId: job.kernelId },
            // When the gateway received the bundle: the relay row's createdAt.
            ...(receivedAtSeconds(r.createdAt) !== undefined ? { receivedAt: receivedAtSeconds(r.createdAt) } : {}),
          }));
        const kernelRow = repos.kernels.findById(job.kernelId);
        seam2RegisteredSigner = registeredSignerInputFromColumns(kernelRow ?? null);
      }
      // No operatorPrincipalId: the gateway has no authoritative funded operator
      // (kernel.operatorAddress is self-registered; the funded operator J1 is the
      // oracle's, at /settle), so session-signed evidence never anchors here.
      const settlementEvidence = await resolveSettlementEvidence({
        deviceBundles: seam2DeviceBundles,
        registeredSigner: seam2RegisteredSigner,
        fallback: {
          bundleHash: gatewayBundleHash,
          kernelSignature: gatewaySignature,
          assuranceTier: jobAssuranceTier,
        },
        verifyEd25519: naclEd25519Verify,
        gateOpen: seam2GateOpen,
      });
      // The settlement anchor: drives the stored bundle, IPFS archive, oracle verify,
      // driveSettlement and the EAS bridge below. The gateway placeholder + envelope
      // hash when the gate is closed (the default).
      const bundleHash = settlementEvidence.bundleHash;
      const settlementSignature = settlementEvidence.kernelSignature;
      // A device anchor IS a verified relayed row: pin that row, whose events open
      // to its digest and which keeps its delegation, instead of restating its
      // digest over the gateway's own events (LO-EV-9 review R1). Recovery
      // (/resume-settlement) re-verifies exactly this pinned row.
      const deviceAnchored =
        settlementEvidence.source === "device" && settlementEvidence.bundleId !== undefined;
      const anchorBundleId = deviceAnchored ? (settlementEvidence.bundleId as string) : bundleId;
      const anchorEvents = deviceAnchored
        ? ((settlementEvidence.events ?? []) as typeof events)
        : events;

      // ── 2. Store evidence bundle ───────────────────────────────────
      // The gateway's own record of the job, always under its OWN canonical
      // envelope hash and placeholder signature, so every stored row's digest
      // opens to its own events.
      repos.evidence.insert({
        id: bundleId,
        jobId,
        stepId: job.stepId,
        kernelId: job.kernelId,
        assuranceTier: jobAssuranceTier,
        bundleHash: gatewayBundleHash,
        kernelSignature: gatewaySignature,
        createdAt: now,
      });

      if (events.length > 0) {
        repos.evidence.insertEvents(
          events.map((ev) => ({
            id: ev.id,
            bundleId,
            type: ev.type,
            timestamp: ev.timestamp,
            source: ev.source,
            payload: ev.payload as Record<string, unknown>,
            hash: ev.hash,
          })),
        );
      }

      // Pin the settlement anchor on the job (the device row when device-anchored).
      repos.jobs.update(jobId, {
        evidenceBundleId: anchorBundleId,
        status: "evidence_submitted",
      });

      // ── 2b. Archive evidence to IPFS (Storacha/Helia) — best effort ──
      let ipfsCid: string | null = null;
      try {
        const storage = await getEvidenceStorage();
        const archiveResult = await storage.archiveBundle({
          id: anchorBundleId,
          jobId,
          stepId: job.stepId,
          kernelId: job.kernelId,
          assuranceTier: jobAssuranceTier,
          bundleHash,
          events: anchorEvents,
          // StoredSignature → the strict spec Signature (device sig or the gateway
          // placeholder; both ed25519, signer is a 0x-string).
          kernelSignature: settlementSignature as Signature,
          createdAt: now,
        });
        ipfsCid = archiveResult.cid;
        pipelineTelemetry.emit(jobId, "evidence_archive", "completed", {
          metadata: { cid: ipfsCid, bundleId: anchorBundleId },
        });
      } catch (archiveErr) {
        console.warn("[complete] Evidence IPFS archive failed, using mock CID:", archiveErr instanceof Error ? archiveErr.message : archiveErr);
        // Generate a deterministic mock CID so the pipeline always returns one
        try {
          const { StorachaStorageService } = await import("@pcc/kernel/storacha-storage");
          const mockStorage = new StorachaStorageService({ mock: true });
          await mockStorage.init();
          const mockResult = await mockStorage.archiveBundle({
            id: anchorBundleId, jobId, stepId: job.stepId, kernelId: job.kernelId,
            assuranceTier: jobAssuranceTier, bundleHash: bundleHash as `sha256:${string}`, events: anchorEvents as any,
            kernelSignature: settlementSignature as Signature,
            createdAt: now,
          });
          ipfsCid = mockResult.cid;
        } catch { /* truly best-effort */ }
      }

      // ── 2c. ZK commitment + Starknet anchor — best effort ───────────
      let starknetTxHash: string | null = null;
      try {
        const starknetService = new StarknetProofAnchoringService({
          mock: true, // Use mock until Starknet account is deployed
        });
        // Create a commitment from the evidence hash
        const commitment = await commitmentService.createCommitment(bundleHash as any);
        // Generate tier compliance proof
        const proof = await zkProofService.generateProof("tier_compliance", commitment as any, {
          requiredTier: jobAssuranceTier,
          bundleHash,
        });
        // Anchor on Starknet
        const anchor = await starknetService.anchorProof(proof);
        starknetTxHash = anchor.txHash;
        pipelineTelemetry.emit(jobId, "verification_request", "completed", {
          metadata: { txHash: starknetTxHash, proofId: proof.id, mode: starknetService.isMock() ? "mock" : "real" },
        });
      } catch (zkErr) {
        console.warn("[complete] ZK/Starknet anchor failed (best-effort):", zkErr instanceof Error ? zkErr.message : zkErr);
      }

      // ── 3. Execution scopes — left active (not revoked on completion) ──
      // Scopes remain active so the operator/agent can continue using them
      // for follow-up tool calls (camera, diagnostics, etc.) until expiry.

      // ── 4. Find escrow and submit evidence hash ────────────────────
      // Look up the session that created this job to find the escrow
      const sessionRow = db.select().from(negotiationSessions)
        .where(eq(negotiationSessions.jobId, jobId))
        .get();

      let escrowAddress: string | null = sessionRow?.escrowAddress ?? null;
      let escrowId: string | null = null;

      // Also try to find the escrow by cwmId
      if (sessionRow?.cwmId) {
        const escrow = repos.escrows.findByCwm(sessionRow.cwmId);
        if (escrow) {
          escrowId = escrow.id;
          escrowAddress = escrow.contractAddress;

          // Update escrow milestone with evidence hash
          const milestones = repos.escrows.findMilestonesByEscrow(escrow.id);
          if (milestones.length > 0) {
            repos.escrows.updateMilestoneStatus(milestones[0].id, "evidence_submitted");
          }
        }
      }

      // ── 4a-V2. On-chain evidence leg via the settlement crank (V2 path) ──
      // driveSettlement reads the milestone's receipt-confirmed on-chain state,
      // funds it if needed, and submits the evidence hash — mapping the contract's
      // own dedup reverts to already-done, so this is safe to re-run. It returns the
      // on-chain stepId (the oracle binds its EAS mint to it) and stops at
      // needs_input:eas_uid; the UID is minted at 4b and bound at 4c.
      //
      // This replaces the former one-shot submitEvidence. We no longer swallow the
      // result and silently fall back to V1: expected reverts are handled INSIDE the
      // crank, and an unexpected chain error (RPC down) leaves the job recoverable at
      // 'evidence_submitted' for resume-settlement to re-drive — it is not hidden.
      const hasRealEscrow =
        !!escrowAddress && escrowAddress.startsWith("0x") && !escrowAddress.startsWith("mock");

      // V3 Mode-A (oracle-free approveAndRelease) settlement REMOVED per owner directive — everything through the oracle. V3 escrows now settle via the oracle-attested Mode-B dispatch below.

      let onChainStepId: `0x${string}` | undefined;
      let evidenceTxHash: string | null = null;
      if (useEasV2() && hasRealEscrow && escrowWriteEnabled()) {
        try {
          const drive = await driveSettlement(escrowAddress as `0x${string}`, 0, {
            evidenceBundleHash: bundleHash as `0x${string}`,
          });
          onChainStepId = (drive.stepId as `0x${string}` | undefined) ?? undefined;
          evidenceTxHash = drive.steps.find((s) => s.action === "submitEvidence")?.txHash ?? null;
        } catch (evErr) {
          // The milestone stays where the crank left it on-chain; a fresh read on the
          // next drive (4c below, or resume-settlement) resumes it. Surface, don't hide.
          pipelineTelemetry.emit(jobId, "settlement_claim", "failed", {
            metadata: { path: "crank-evidence", error: evErr instanceof Error ? evErr.message : String(evErr) },
          });
        }
      }

      // ── 4b. Oracle verification ─────────────────────────────────────
      // Every settlement must pass through the PCC Verification Oracle.
      // If PCC_ORACLE_KEY is not set, falls back to mock (dev/test).
      // V2: ask the oracle to MINT an on-chain EAS attestation bound to the
      // real milestone stepId; the returned UID is bound on-chain below.
      const oracleResponse = await verifyWithOracle({
        escrowAddress: escrowAddress ?? "0x0000000000000000000000000000000000000000",
        jobId,
        kernelId: job.kernelId,
        evidenceHash: bundleHash,
        assuranceTier: jobAssuranceTier,
        chainId: resolveChainId(),
        ...(useEasV2()
          ? {
              mintEasAttestation: true,
              schemaUid: process.env.PCC_EVIDENCE_SCHEMA_UID,
              // Prefer the real on-chain stepId; fall back to the job's stepId
              // string (hashed by the oracle) when no real escrow is available.
              stepId: onChainStepId ?? job.stepId,
            }
          : {}),
      });

      if (!oracleResponse.result.verified) {
        return reply.status(422).send({
          error: "oracle_verification_failed",
          reason: oracleResponse.result.reason,
          checks: oracleResponse.result.checks,
        });
      }

      // Store the attestation for potential on-chain submission
      const oracleAttestation = oracleResponse.attestation;

      // ── 4c. EAS attestation bridge (V2) — gated by PCC_USE_EAS_V2 ─────
      // V1 default: no on-chain attestation bridge here (backwards compatible —
      // settlement below is unchanged). V2 (PCC_USE_EAS_V2=true): build the
      // pcc.evidence.v1 attestation payload from the oracle verdict + evidence
      // and, when the gateway can write to a real escrow and an oracle-minted
      // EAS UID is supplied, bind it on-chain via
      // MilestoneEscrowV2.submitAttestation(uid). This replaces the removed
      // Alkahest bridge.
      let easBridge: Record<string, unknown> | null = null;
      if (useEasV2()) {
        try {
          const easMeta = buildEasAttestationMetadata({
            jobId,
            kernelId: job.kernelId,
            stepId: job.stepId,
            evidenceBundleHash: bundleHash,
            ipfsCid: ipfsCid ?? "",
            assuranceTier: jobAssuranceTier,
            oracleVerified: oracleResponse.result.verified,
            recipient: escrowAddress && escrowAddress.startsWith("0x") ? escrowAddress : undefined,
          });

          easBridge = {
            schema: easMeta.schema,
            schemaUid: easMeta.schemaUid,
            recipient: easMeta.recipient,
            encoded: easMeta.encoded,
            evidenceTxHash,
            submitted: false,
            attestationUid: null as string | null,
            attestationTxHash: null as string | null,
          };

          // EAS UID to bind on-chain: prefer the oracle-minted UID (orchestrated
          // path), fall back to a caller-supplied body.easUid (explicit bind).
          const oracleEasUid = oracleResponse.easAttestation?.easUid;
          const bodyEasUid = typeof body.easUid === "string" ? body.easUid : undefined;
          const easUid = (oracleEasUid ?? bodyEasUid) as `0x${string}` | undefined;

          if (easUid) easBridge.attestationUid = easUid;

          // Bind the attestation on-chain against a REAL escrow with write enabled
          // (the mock/dev easUid 0xea… is returned but never sent to a live chain).
          // Dispatch on the escrow's DB version: V3 escrows (created via the V3
          // factory) settle through the oracle-attested Mode-B path (submitEvidenceV3
          // → submitAttestationV3); V2 escrows route through the idempotent settlement
          // crank (driveSettlement), which is V2-only. Falls back to V2 when the row
          // is missing.
          if (easUid && hasRealEscrow && escrowWriteEnabled() && escrowAddress) {
            const escrowRow = repos.escrows.findByContractAddress(escrowAddress);
            const escrowVersion =
              (escrowRow?.version as "v2" | "v3" | null | undefined) ?? "v2";
            if (escrowVersion === "v3") {
              // V3 requires the evidence hash on-chain BEFORE the attestation binds —
              // submitAttestation reverts "Evidence not submitted" otherwise. Submit the
              // bundle hash as bytes32 (the same 0x<hex> the oracle attests) and wait
              // for it to mine so the attestation read below sees it.
              try {
                const evidenceBytes32 = (
                  bundleHash.startsWith("sha256:")
                    ? `0x${bundleHash.slice("sha256:".length)}`
                    : bundleHash
                ) as `0x${string}`;
                const evV3 = await submitEvidenceV3(
                  0,
                  evidenceBytes32,
                  escrowAddress as `0x${string}`,
                );
                easBridge.evidenceTxHash = evV3.transactionHash;
                await waitForReceipt(evV3.transactionHash as `0x${string}`);
              } catch (evErr) {
                console.warn(
                  "[complete] V3 on-chain evidence submit failed (attestation will likely revert):",
                  evErr instanceof Error ? evErr.message : evErr,
                );
              }
              const submitted = await submitAttestationV3(0, easUid, escrowAddress as `0x${string}`);
              easBridge.submitted = true;
              easBridge.attestationTxHash = submitted.transactionHash;
              easBridge.escrowVersion = escrowVersion;
            } else {
              // V2: the idempotent settlement crank binds the attestation (and, for a
              // zero-window tier-0 milestone, releases). Passing BOTH the evidence hash
              // and the UID makes the drive self-healing — if 4a's evidence submit did
              // not land it resubmits evidence first, then binds. A re-run maps
              // "Attestation already used" / "Evidence not submitted" to already-done.
              const drive = await driveSettlement(escrowAddress as `0x${string}`, 0, {
                evidenceBundleHash: bundleHash as `0x${string}`,
                easUid,
              });
              const attestStep = drive.steps.find((s) => s.action === "submitAttestation");
              // The attestation is on-chain once the milestone reached Attested or beyond.
              easBridge.submitted = drive.finalStatus === "Attested" || drive.settled;
              easBridge.attestationTxHash = attestStep?.txHash ?? null;
              easBridge.driveOutcome = drive.outcome;
              easBridge.settledOnChain = drive.settled;
              easBridge.escrowVersion = escrowVersion;
            }
          }

          pipelineTelemetry.emit(jobId, "settlement_claim", "completed", {
            metadata: {
              path: easBridge.escrowVersion === "v3" ? "eas-v3-mode-b" : "eas-v2",
              easSchema: easMeta.schema,
              easSubmitted: easBridge.submitted,
              easUid: easBridge.attestationUid ?? null,
            },
          });
        } catch (easErr) {
          console.warn("[complete] EAS attestation bridge failed (best-effort):", easErr instanceof Error ? easErr.message : easErr);
        }
      }

      // ── 5. Settlement ──────────────────────────────────────────────
      let settlementStatus = "evidence_submitted";
      let settledAt: string | null = null;

      if (isMockSettlement()) {
        // Mock settlement: auto-settle after marking evidence
        repos.jobs.updateStatus(jobId, "settled");
        settledAt = now;
        settlementStatus = "settled";

        if (escrowId) {
          repos.escrows.updateStatus(escrowId, "completed");
          const milestones = repos.escrows.findMilestonesByEscrow(escrowId);
          for (const ms of milestones) {
            repos.escrows.updateMilestoneStatus(ms.id, "released");
          }
        }
      } else {
        // Real settlement: update status to evidence_submitted and wait for challenge window
        repos.jobs.updateStatus(jobId, "evidence_submitted");
        settlementStatus = "evidence_submitted";
      }

      pipelineTelemetry.emit(jobId, "settlement_complete", "completed", {
        metadata: {
          bundleId: anchorBundleId,
          bundleHash,
          escrowAddress,
          settlementStatus,
          mockSettlement: isMockSettlement(),
          toolCallCount: auditTrail.length,
          oracleVerified: oracleResponse.result.verified === true,
          oracleReason: oracleResponse.result.reason,
        },
      });

      return {
        jobId,
        status: settlementStatus,
        evidenceBundleId: anchorBundleId,
        evidenceHash: bundleHash,
        escrowAddress,
        escrowId,
        settledAt,
        ipfsCid,
        starknetAnchorTxHash: starknetTxHash,
        eas: easBridge,
        scopesRevoked: 0,
        toolCallsRecorded: auditTrail.length,
        oracleVerified: oracleResponse.result.verified,
        oracleAttestation: oracleAttestation ? {
          signature: oracleAttestation.signature,
          nonce: oracleAttestation.nonce,
          timestamp: oracleAttestation.timestamp,
        } : null,
        message: isMockSettlement()
          ? "Job completed and settled (mock settlement). Oracle verification passed."
          : "Job completed. Oracle verified. Evidence submitted. Awaiting challenge window expiry for settlement.",
      };
    } catch (err) {
      // Release the completion claim if we still hold it and hadn't yet recorded
      // evidence (status still 'completing'), so a legitimate retry can proceed.
      // Once we've advanced to evidence_submitted the WHERE matches nothing and
      // the retry stays blocked — the evidence already exists.
      if (claimedOriginalStatus !== undefined) {
        try {
          getStore().db
            .update(schema.jobs)
            .set({ status: claimedOriginalStatus })
            .where(and(eq(schema.jobs.id, jobId), eq(schema.jobs.status, "completing")))
            .run();
        } catch {
          // best-effort — a stuck 'completing' row is still safe (blocks double-run)
        }
      }
      return reply.status(500).send({
        error: "completion_failed",
        details: err instanceof Error ? err.message : String(err),
      });
    }
  }

storage.archiveBundle({
          id: anchorBundleId,
          jobId,
          stepId: job.stepId,
          kernelId: job.kernelId,
          assuranceTier: jobAssuranceTier,
          bundleHash,
          events: anchorEvents,
          // StoredSignature → the strict spec Signature (device sig or the gateway
          // placeholder; both ed25519, signer is a 0x-string).
          kernelSignature: settlementSignature as Signature,
          createdAt: now,
        })

async (req, reply) => {
    const { jobId } = req.params;
    // Set true once we hold the 'completing' claim, so a later failure can release
    // it back to 'evidence_submitted' (keeping the job recoverable, never trapped).
    let reclaimed = false;

    try {
      const repos = getRepos();
      const { db } = getStore();

      const job = repos.jobs.findById(jobId);
      if (!job) {
        return reply.status(404).send({ error: "Job not found" });
      }

      // Single-winner reclaim: flip ONLY an 'evidence_submitted' job into
      // 'completing'. Excludes settled/completed/failed/cancelled/completing, so a
      // settled job or an in-flight /complete is never disturbed, and two
      // concurrent resumes can't both win.
      const claimed = db
        .update(schema.jobs)
        .set({ status: "completing" })
        .where(and(eq(schema.jobs.id, jobId), eq(schema.jobs.status, "evidence_submitted")))
        .returning()
        .all();
      if (claimed.length !== 1) {
        return reply.status(409).send({
          error: "Job is not in a resumable state (must be 'evidence_submitted' and not already settling/settled)",
          status: job.status,
        });
      }
      reclaimed = true;

      // Reuse the evidence /complete PINNED as this job's settlement anchor
      // (job.evidenceBundleId) -- never "the latest row", which any later relay
      // write could supply (LO-EV-9 review R1) -- and re-verify it before any
      // settlement step: a device anchor must pass the subject binding and the
      // registered-signer signature again; a gateway anchor must recompute from
      // its stored envelope. Anything else releases the claim and refuses.
      const pinnedBundle = job.evidenceBundleId ? repos.evidence.findById(job.evidenceBundleId) : undefined;
      const pinnedEvents = pinnedBundle
        ? repos.evidence.findEventsByBundle(pinnedBundle.id).map((ev) => ({
            id: ev.id,
            type: ev.type,
            timestamp: ev.timestamp,
            source: ev.source,
            payload: ev.payload,
            hash: ev.hash,
          }))
        : [];
      const pinnedCheck = await verifyPinnedSettlementEvidence({
        jobId,
        kernelId: job.kernelId,
        row: pinnedBundle
          ? {
              ...pinnedBundle,
              kernelSignature: pinnedBundle.kernelSignature as StoredSignature,
            }
          : undefined,
        events: pinnedEvents,
        registeredSigner: registeredSignerInputFromColumns(repos.kernels.findById(job.kernelId) ?? null),
        verifyEd25519: naclEd25519Verify,
      });
      if (!pinnedBundle || !pinnedCheck.ok) {
        repos.jobs.updateStatus(jobId, "evidence_submitted");
        reclaimed = false;
        return reply.status(409).send({
          error: "The job's pinned settlement evidence is missing or fails verification; recovery settles only the evidence /complete anchored",
          reason: pinnedCheck.ok ? "no-pinned-evidence" : pinnedCheck.reason,
          status: "evidence_submitted",
        });
      }
      const latestBundle = pinnedBundle;
      const bundleId = pinnedBundle.id;
      const bundleHash = pinnedBundle.bundleHash;
      // The chain takes the pinned digest as bytes32 (the same 0x<hex> /complete's
      // V3 path submits and the oracle attests), never the sha256:-tagged string.
      const chainEvidenceHash = (
        bundleHash.startsWith("sha256:") ? `0x${bundleHash.slice("sha256:".length)}` : bundleHash
      ) as `0x${string}`;

      // Real negotiated tier (A-3 consistency): the on-chain milestone requiredTier.
      const tierSessionRow = db
        .select()
        .from(negotiationSessions)
        .where(eq(negotiationSessions.jobId, jobId))
        .get();
      const jobAssuranceTier = toTier(
        (tierSessionRow?.contractTerms as Record<string, unknown> | null)?.assuranceTier
          ?? latestBundle.assuranceTier
          ?? 0,
      );

      // Resolve escrow (same lookup as /complete). If settlement is ALREADY
      // recorded on-chain (escrow completed or a milestone released), do not
      // re-settle — reconcile the job to 'settled' and return. This is the
      // "IFF no settlement recorded" guard.
      let escrowAddress: string | null = tierSessionRow?.escrowAddress ?? null;
      let escrowId: string | null = null;
      if (tierSessionRow?.cwmId) {
        const escrow = repos.escrows.findByCwm(tierSessionRow.cwmId);
        if (escrow) {
          escrowId = escrow.id;
          escrowAddress = escrow.contractAddress;
          const milestones = repos.escrows.findMilestonesByEscrow(escrow.id);
          const alreadyReleased =
            escrow.status === "completed" || milestones.some((m) => m.status === "released");
          if (alreadyReleased) {
            repos.jobs.updateStatus(jobId, "settled");
            reclaimed = false;
            return {
              jobId,
              status: "settled",
              resumed: true,
              alreadySettled: true,
              evidenceBundleId: bundleId,
              escrowAddress,
              escrowId,
              assuranceTier: jobAssuranceTier,
              message: "Escrow already settled on-chain; job reconciled to settled (no re-settle).",
            };
          }
        }
      }

      // Whether to re-drive the CHAIN (not just the DB) for this recovery. The old
      // resume deliberately never touched the chain — "re-submitting on-chain evidence
      // would risk a double write". driveSettlement removes that fear: the contract
      // dedups every post-creation op by revert, and the crank maps those reverts to
      // already-done, so re-driving is a safe no-op past whatever already landed.
      const hasRealEscrow =
        !!escrowAddress && escrowAddress.startsWith("0x") && !escrowAddress.startsWith("mock");
      const v2ChainDrive = useEasV2() && hasRealEscrow && escrowWriteEnabled();

      // First chain pass: read the milestone's TRUE on-chain state and advance it —
      // fund + submit evidence if they never landed, and (the core recovery) RELEASE
      // an already-Attested milestone whose challenge window has closed, which needs
      // no oracle at all. Returns the on-chain stepId for the mint below.
      let onChainStepId: `0x${string}` | undefined;
      let chainOutcome: string | undefined;
      let chainSettled = false;
      if (v2ChainDrive) {
        try {
          const d1 = await driveSettlement(escrowAddress as `0x${string}`, 0, {
            evidenceBundleHash: chainEvidenceHash,
          });
          onChainStepId = (d1.stepId as `0x${string}` | undefined) ?? undefined;
          chainOutcome = d1.outcome;
          chainSettled = d1.settled;
        } catch (e1) {
          pipelineTelemetry.emit(jobId, "settlement_claim", "failed", {
            metadata: { path: "resume-crank-evidence", error: e1 instanceof Error ? e1.message : String(e1) },
          });
        }
      }

      // F4: if the first pass ALREADY read-confirmed an on-chain release (money moved),
      // the oracle verdict is moot — reconcile the DB to 'settled' and short-circuit
      // BEFORE the oracle gate. Without this, an oracle verified:false below resets the
      // job to 'evidence_submitted' and the DB permanently lags a real release (every
      // resume repeating the 422). Safe because driveSettlement reports settled ONLY from
      // a landed receipt or a read-confirmed Released (settlement-crank F1 invariant), and
      // when chainSettled the oracle mint was already skipped (nothing is lost by skipping
      // the gate).
      if (v2ChainDrive && chainSettled) {
        const nowIso = new Date().toISOString();
        repos.jobs.updateStatus(jobId, "settled");
        if (escrowId) {
          repos.escrows.updateStatus(escrowId, "completed");
          for (const ms of repos.escrows.findMilestonesByEscrow(escrowId)) {
            repos.escrows.updateMilestoneStatus(ms.id, "released");
          }
        }
        reclaimed = false;
        pipelineTelemetry.emit(jobId, "settlement_complete", "completed", {
          metadata: {
            path: "resume-settlement-chain-preconfirmed",
            bundleId,
            bundleHash,
            escrowAddress,
            settlementStatus: "settled",
            assuranceTier: jobAssuranceTier,
            mockSettlement: isMockSettlement(),
            chainOutcome: chainOutcome ?? null,
            chainSettled: true,
          },
        });
        return {
          jobId,
          status: "settled",
          resumed: true,
          evidenceBundleId: bundleId,
          evidenceHash: bundleHash,
          escrowAddress,
          escrowId,
          settledAt: nowIso,
          assuranceTier: jobAssuranceTier,
          oracleVerified: true, // release already landed on-chain; oracle gate short-circuited
          chainOutcome: chainOutcome ?? null,
          chainSettled: true,
          message:
            "Settlement resumed: milestone already released on-chain (read-confirmed). Job reconciled to settled; oracle gate short-circuited.",
        };
      }

      // Oracle gate — verify the reused evidence hash. For a real V2 escrow that is
      // not already settled on-chain we ALSO mint the EAS attestation (bound to the
      // on-chain stepId) so the second pass can bind it; the mock / non-chain path
      // stays a pure verification, unchanged.
      const oracleResponse = await verifyWithOracle({
        escrowAddress: escrowAddress ?? ZERO_ADDRESS,
        jobId,
        kernelId: job.kernelId,
        evidenceHash: bundleHash,
        assuranceTier: jobAssuranceTier,
        chainId: resolveChainId(),
        ...(v2ChainDrive && !chainSettled
          ? {
              mintEasAttestation: true,
              schemaUid: process.env.PCC_EVIDENCE_SCHEMA_UID,
              stepId: onChainStepId ?? job.stepId,
            }
          : {}),
      });
      if (!oracleResponse.result.verified) {
        // Not verified: release the claim back to 'evidence_submitted' so a future
        // resume (e.g. after a transient oracle outage) can try again.
        repos.jobs.updateStatus(jobId, "evidence_submitted");
        reclaimed = false;
        return reply.status(422).send({
          error: "oracle_verification_failed",
          reason: oracleResponse.result.reason,
          checks: oracleResponse.result.checks,
        });
      }

      // Second chain pass: bind the freshly-minted attestation and release if the
      // window has already closed (idempotent — a re-run maps the dedup reverts to
      // already-done). Skipped when the first pass already settled on-chain.
      if (v2ChainDrive && !chainSettled) {
        const easUid = oracleResponse.easAttestation?.easUid as `0x${string}` | undefined;
        if (easUid) {
          try {
            const d2 = await driveSettlement(escrowAddress as `0x${string}`, 0, {
              evidenceBundleHash: chainEvidenceHash,
              easUid,
            });
            chainOutcome = d2.outcome;
            chainSettled = d2.settled;
          } catch (e2) {
            pipelineTelemetry.emit(jobId, "settlement_claim", "failed", {
              metadata: { path: "resume-crank-attest", error: e2 instanceof Error ? e2.message : String(e2) },
            });
          }
        }
      }

      // Settlement DB status. Mock: settle immediately (unchanged). Real: reconcile to
      // 'settled' ONLY when the milestone actually released on-chain during this
      // resume; otherwise it stays 'evidence_submitted' (still awaiting the window),
      // resumable again once the window closes.
      const nowIso = new Date().toISOString();
      let settlementStatus = "evidence_submitted";
      let settledAt: string | null = null;
      if (isMockSettlement()) {
        repos.jobs.updateStatus(jobId, "settled");
        settledAt = nowIso;
        settlementStatus = "settled";
        if (escrowId) {
          repos.escrows.updateStatus(escrowId, "completed");
          for (const ms of repos.escrows.findMilestonesByEscrow(escrowId)) {
            repos.escrows.updateMilestoneStatus(ms.id, "released");
          }
        }
      } else if (chainSettled) {
        repos.jobs.updateStatus(jobId, "settled");
        settledAt = nowIso;
        settlementStatus = "settled";
        if (escrowId) {
          repos.escrows.updateStatus(escrowId, "completed");
          for (const ms of repos.escrows.findMilestonesByEscrow(escrowId)) {
            repos.escrows.updateMilestoneStatus(ms.id, "released");
          }
        }
      } else {
        repos.jobs.updateStatus(jobId, "evidence_submitted");
        settlementStatus = "evidence_submitted";
      }
      reclaimed = false;

      pipelineTelemetry.emit(jobId, "settlement_complete", "completed", {
        metadata: {
          path: "resume-settlement",
          bundleId,
          bundleHash,
          escrowAddress,
          settlementStatus,
          assuranceTier: jobAssuranceTier,
          mockSettlement: isMockSettlement(),
          oracleVerified: oracleResponse.result.verified === true,
          chainOutcome: chainOutcome ?? null,
          chainSettled,
        },
      });

      return {
        jobId,
        status: settlementStatus,
        resumed: true,
        evidenceBundleId: bundleId,
        evidenceHash: bundleHash,
        escrowAddress,
        escrowId,
        settledAt,
        assuranceTier: jobAssuranceTier,
        oracleVerified: oracleResponse.result.verified,
        chainOutcome: chainOutcome ?? null,
        chainSettled,
        message: isMockSettlement()
          ? "Settlement resumed from existing evidence (mock settlement). Oracle verification passed."
          : chainSettled
            ? "Settlement resumed and released on-chain via the crank. Job reconciled to settled."
            : "Settlement resumed from existing evidence. Oracle verified. Awaiting challenge window expiry.",
      };
    } catch (err) {
      // Release the reclaim so the job stays recoverable (never trapped at
      // 'completing'). Guarded on the status we set, matching /complete's catch.
      if (reclaimed) {
        try {
          getStore().db
            .update(schema.jobs)
            .set({ status: "evidence_submitted" })
            .where(and(eq(schema.jobs.id, jobId), eq(schema.jobs.status, "completing")))
            .run();
        } catch {
          // best-effort — a stuck 'completing' row still blocks double-settle
        }
      }
      return reply.status(500).send({
        error: "resume_settlement_failed",
        details: err instanceof Error ? err.message : String(err),
      });
    }
  }

async (req, reply) => {
    const body = req.body as Record<string, unknown> | undefined;
    if (!body) {
      return reply.status(400).send({ error: "Request body is required" });
    }

    const { kernelId, capabilityType, parameters, paymentMethod, userAgentId: namedBuyer } = body as any;

    if (!kernelId || !capabilityType || !namedBuyer) {
      return reply.status(400).send({
        error: "kernelId, capabilityType, and userAgentId are required",
      });
    }

    // N133 rule 1: the buyer is the caller's proven identity, or the admin acts for it. The buyer
    // holds the write scope minted below, so a claim or a mismatch is refused before anything
    // (session, escrow, job, scope) is created.
    const binding = bindBuyer(authorityOf(req), namedBuyer);
    if (!binding.ok) return reply.status(binding.status).send(binding.body);
    const userAgentId = binding.buyer;

    try {
      const { db } = getStore();
      const now = new Date();

      // Load operator policy
      const policyRow = db.select().from(operatorPolicies)
        .where(eq(operatorPolicies.kernelId, kernelId))
        .get();
      const policy = (policyRow?.policy ?? DEFAULT_OPERATOR_POLICY) as unknown as OperatorPolicy;

      if (policy.emergencyStop) {
        return reply.status(503).send({ error: "Operator has activated emergency stop" });
      }

      // ── Create fast-track session ───────────────────────────────────
      const sessionId = `sess-${crypto.randomUUID()}`;
      const expiresAt = new Date(now.getTime() + SESSION_TTL_MS).toISOString();

      const constraints = {
        allowedMaterials: policy.allowedMaterials,
        maxDurationMs: policy.maxDurationMs,
        operatingHours: policy.operatingHours,
        timezone: policy.timezone,
        requireEscrow: policy.requireEscrow,
        maxTemperatureCelsius: policy.maxTemperatureCelsius,
      };

      const selections = parameters ?? {};
      const sanitizedSelections: Record<string, unknown> = {};
      for (const [key, value] of Object.entries(selections)) {
        sanitizedSelections[key] = typeof value === "string" ? sanitizeText(value) : value;
      }

      // The quote is the operator's REGISTERED price for the selected capability (N98): never a
      // template hint, never a default. Exactly one capability of this type on this kernel; job
      // creation (createJobFromSession) then resolves the same one.
      const candidates = getRepos().capabilities.findByKernel(kernelId).filter((c) => c.type === capabilityType);
      if (candidates.length === 0) {
        return reply.status(404).send({ error: "capability_not_found", message: `No ${capabilityType} capability is registered on this kernel.` });
      }
      if (candidates.length > 1) {
        return reply.status(409).send({ error: "capability_ambiguous", message: `This kernel registers more than one ${capabilityType} capability, so no single price applies.` });
      }
      const registered = registeredQuotePrice(candidates[0]!.pricing);
      if (!registered.ok) {
        if (registered.reason === "unsupported-currency") {
          return reply.status(422).send({
            error: "capability_price_unsupported_currency",
            currency: registered.currency,
            settlementCurrency: SETTLEMENT_CURRENCY,
            message: `This capability is registered in ${registered.currency}, but this gateway settles only in ${SETTLEMENT_CURRENCY}. There is no conversion.`,
          });
        }
        return reply.status(422).send({ error: "capability_price_undeclared", reason: registered.reason, message: "This capability declares no usable price, so it cannot be quoted." });
      }
      const quantityRaw = sanitizedSelections.quantity;
      const quantity = quantityRaw === undefined ? 1 : quantityRaw;
      if (typeof quantity !== "number" || !Number.isSafeInteger(quantity) || quantity < 1 || quantity > MAX_QUOTE_QUANTITY) {
        return reply.status(400).send({ error: "invalid_quantity", message: `quantity must be a whole number from 1 to ${MAX_QUOTE_QUANTITY}.` });
      }
      // F4: every rule is validated BEFORE any rule is applied, whether enabled or not — a malformed
      // policy must never reach quoting, let alone money. All before any side effect (no session row
      // exists yet).
      const rulesValidation = validatePricingRules(policy.pricingRules);
      if (!rulesValidation.ok) {
        return reply.status(422).send({
          error: "operator_pricing_policy_invalid",
          ruleIndex: rulesValidation.ruleIndex,
          ...(rulesValidation.ruleId !== undefined ? { ruleId: rulesValidation.ruleId } : {}),
          reason: rulesValidation.reason,
        });
      }
      // Exact arithmetic in cents up to the rules: the registered price times the quantity, never
      // below the operator's declared minimum. exactQuoteTotal works entirely in bigint (F1): no
      // money value ever passes through `Number`.
      let subtotalCents = registered.cents * BigInt(quantity);
      if (registered.minimumCents !== null && subtotalCents < registered.minimumCents) subtotalCents = registered.minimumCents;
      const applicableRules = pricingRulesThatApply(rulesValidation.rules, { quantity, material: sanitizedSelections.material });
      const { totalCents, adjustments } = exactQuoteTotal(subtotalCents, applicableRules);

      const quote = {
        basePrice: centsToDecimal(registered.cents),
        adjustments,
        totalPrice: centsToDecimal(totalCents),
        currency: registered.currency,
        // Rates the registered pricing declares per unit of usage, which a discovery quote cannot
        // measure: shown so the buyer sees them, and not charged by this quote.
        ...(Object.keys(registered.usage).length > 0 ? { unquotedUsage: registered.usage } : {}),
        bondAmount: "0.00",
        challengeWindowSeconds: 0,
        validUntil: new Date(Date.now() + 30 * 60_000).toISOString(),
      };

      const stepId = `step-${crypto.randomUUID().slice(0, 8)}`;

      const contractTerms = {
        milestones: [{
          stepId,
          amount: quote.totalPrice,
          bondAmount: quote.bondAmount,
          challengeWindowSeconds: quote.challengeWindowSeconds,
        }],
        deadline: new Date(Date.now() + 24 * 60 * 60_000).toISOString(),
        assuranceTier: 0,
        payer: "0x0000000000000000000000000000000000000000",
        operator: "0x0000000000000000000000000000000000000000",
        token: "0x6c7ce5d5decee9983feaa3e637ea3fe3e6945cdb",
      };

      const jobId = `job-${crypto.randomUUID().slice(0, 12)}`;
      const cwmId = `cwm-${crypto.randomUUID().slice(0, 12)}`;

      const transitions: SessionTransition[] = [
        { from: "created", to: "created", timestamp: now.toISOString(), actor: userAgentId, reason: "Fast-track session created" },
        { from: "created", to: "configuring", timestamp: now.toISOString(), actor: userAgentId, reason: "Parameters auto-configured" },
        { from: "configuring", to: "quoted", timestamp: now.toISOString(), actor: "system", reason: `Quote computed: ${quote.totalPrice} ${quote.currency}` },
        { from: "quoted", to: "reviewing", timestamp: now.toISOString(), actor: "system", reason: "Contract terms auto-generated" },
        { from: "reviewing", to: "committed", timestamp: now.toISOString(), actor: userAgentId, reason: `Fast-track committed with job ${jobId}` },
      ];

      const session = {
        id: sessionId,
        status: "committed" as SessionStatus,
        userAgentId,
        kernelId,
        capabilityType,
        capabilityId: null,
        network: null,
        selections: sanitizedSelections,
        operatorConstraints: constraints,
        scheduling: {
          earliestAvailable: new Date(Date.now() + 60_000).toISOString(),
          estimatedDuration: "PT30M",
          queuePosition: 0,
          estimatedWaitMs: 60_000,
        },
        quote,
        contractTerms,
        jobId,
        escrowAddress: null as string | null,
        cwmId,
        transitions,
        createdAt: now.toISOString(),
        expiresAt,
        committedAt: now.toISOString(),
      };

      db.insert(negotiationSessions).values(session as any).run();

      // ── Wire: create escrow + job + scope ───────────────────────────
      // Reload from DB to get proper typed row
      const sessionRow = db.select().from(negotiationSessions)
        .where(eq(negotiationSessions.id, sessionId))
        .get();

      if (!sessionRow) {
        return reply.status(500).send({ error: "Failed to create session" });
      }

      const result = await createJobFromSession(sessionRow);

      pipelineTelemetry.emit(result.jobId, "job_accepted", "completed", {
        metadata: {
          sessionId,
          kernelId,
          capabilityType,
          paymentMethod: paymentMethod ?? "testnet-mock",
        },
      });

      return reply.status(201).send({
        sessionId,
        jobId: result.jobId,
        scopeId: result.scopeId,
        scopeStatus: result.scopeStatus,
        escrowId: result.escrowId,
        escrowAddress: result.escrowAddress,
        escrowStatus: result.escrowStatus,
        quote,
        contractTerms,
        message:
          result.scopeStatus === "active"
            ? "Fast-track job created. Scope is active — executor can start making tool calls."
            : result.scopeStatus === "awaiting_acceptance"
              ? "Fast-track job created. Its scope waits for the kernel operator's acceptance (POST /api/operator/scopes/:scopeId/accept)."
              : result.scopeStatus === "awaiting_funding"
                ? "Fast-track job created. Its scope waits for the buyer's own funding of the escrow."
                : "Fast-track job created. The kernel's operator does not accept this buyer: its scope is not live.",
      });
    } catch (err) {
      return reply.status(500).send({
        error: "fast_track_failed",
        details: err instanceof Error ? err.message : String(err),
      });
    }
  }

