async (req, reply) => {
    // Rate limit: max 5 provisions per IP per hour (CRIT-02 fix)
    if (!canProvision(req.ip)) {
      return reply.status(429).send({
        error: "rate_limited",
        message: "Too many API key requests. Try again in an hour.",
        retry_after_seconds: 3600,
      });
    }

    const body = (req.body ?? {}) as {
      email?: string;
      walletAddress?: string;
      name?: string;
      capability?: string;
      /**
       * Optional Ed25519 public key (BYOK). 64 hex chars, optional 0x prefix.
       * Omitted means no signing key on file. The gateway never returns
       * a private key.
       */
      publicKey?: string;
    };

    let operatorId: string;

    // Type guards — prevent object/array/number injection (red team #14, #15)
    if (body.walletAddress !== undefined && typeof body.walletAddress !== "string") {
      return reply.status(400).send({ error: "invalid_type", message: "walletAddress must be a string" });
    }
    if (body.email !== undefined && typeof body.email !== "string") {
      return reply.status(400).send({ error: "invalid_type", message: "email must be a string" });
    }
    if (body.name !== undefined && typeof body.name !== "string") {
      return reply.status(400).send({ error: "invalid_type", message: "name must be a string" });
    }
    if (body.capability !== undefined && typeof body.capability !== "string") {
      return reply.status(400).send({ error: "invalid_type", message: "capability must be a string" });
    }
    if (body.publicKey !== undefined && typeof body.publicKey !== "string") {
      return reply.status(400).send({ error: "invalid_type", message: "publicKey must be a string" });
    }

    if (body.walletAddress) {
      // Wallet address path — format check also implicitly caps length at 42
      if (!/^0x[0-9a-fA-F]{40}$/.test(body.walletAddress)) {
        return reply.status(400).send({
          error: "invalid_wallet_address",
          message: "walletAddress must be a valid EVM address (0x + 40 hex chars)",
        });
      }
      operatorId = body.walletAddress;
    } else if (body.email) {
      // Email path — RFC 5321 max total length is 254
      if (body.email.length > 254) {
        return reply.status(400).send({
          error: "invalid_email",
          message: "Email exceeds 254 character limit",
        });
      }
      if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(body.email)) {
        return reply.status(400).send({
          error: "invalid_email",
          message: "Please provide a valid email address",
        });
      }
      operatorId = body.email;
    } else {
      return reply.status(400).send({
        error: "identifier_required",
        message: "Either email or walletAddress is required to provision an API key",
      });
    }

    try {
      const { rawKey, record } = provisionApiKey({
        operatorId,
        name: body.name,
        description: body.capability
          ? `Operator capability: ${body.capability}`
          : undefined,
        scopes: [...SELF_SERVICE_KEY_SCOPES],
        metadata: {
          capability: body.capability,
          provisionedAt: new Date().toISOString(),
          source: "landing-page",
        },
        publicKey: body.publicKey,
      });

      if (!record) return reply.status(500).send({ error: "provision_failed" });
      auditService.log({
        eventType: "auth.key_provisioned",
        actor: operatorId,
        resourceType: "api_key",
        resourceId: record.id,
        action: "create",
        metadata: {
          name: body.name,
          capability: body.capability,
          ed25519_keypair_source: record.publicKey ? "byok" : "none",
        },
        ip: req.ip,
        userAgent: req.headers["user-agent"],
      });
      trackServerEvent("api_key_provisioned", {
        email: body.email,
        capability: body.capability,
        ed25519_keypair_source: record.publicKey ? "byok" : "none",
      });
      // Surface the trace_id (stamped by `middleware/trace-id.ts`) so the
      // agent can echo it on every subsequent call via `x-pcc-trace-id`.
      // The trace-id middleware also sets it on the response header — the
      // body field is here for clients that read JSON bodies more easily
      // than headers.
      // See docs/AGENT_ONBOARDING_OBSERVABILITY.md.
      const trace_id = (req as unknown as { traceId?: string }).traceId;
      // Provisioning returns only the caller-supplied public key, or null.
      const ed25519Response = {
        public_key: record.publicKey ?? null,
        source: record.publicKey ? "byok" : "none",
      };

      // ── ERC-8004 on-chain identity write (best-effort) ────────────
      // The off-chain DB row is the source of truth at this moment; the
      // on-chain identity is eventually-consistent. If this write fails
      // (network, gas, RPC), the row stays onchain_status='pending' and
      // the retry sweeper will pick it up. Never fail the HTTP request.
      let onchainAttempted = false;
      let onchainResult:
        | { agentId: string; txHash: string; registryAddress: string; chainId: number }
        | undefined;
      if (isIdentityWriteEnabled()) {
        onchainAttempted = true;
        const gatewayUrl =
          process.env.PCC_GATEWAY_URL ?? `${req.protocol}://${req.hostname}`;
        const agentDid =
          operatorId.startsWith("0x") && /^0x[0-9a-fA-F]{40}$/.test(operatorId)
            ? `did:pcc:${operatorId.toLowerCase()}`
            : `did:pcc:${record.id}`;
        try {
          const onchain = await registerAgentOnChain({
            agentDid,
            agentUrl: gatewayUrl,
          });
          getRepos().apiKeys.recordOnchainSuccess(record.id, {
            agentId: onchain.agentId,
            txHash: onchain.txHash,
            registryAddress: onchain.registryAddress,
            chainId: onchain.chainId,
          });
          onchainResult = {
            agentId: String(onchain.agentId),
            txHash: onchain.txHash,
            registryAddress: onchain.registryAddress,
            chainId: onchain.chainId,
          };
          auditService.log({
            eventType: "auth.onchain_identity_written",
            actor: operatorId,
            resourceType: "api_key",
            resourceId: record.id,
            action: "create",
            metadata: onchainResult,
            ip: req.ip,
            userAgent: req.headers["user-agent"],
          });
        } catch (onchainErr) {
          const code = classifyChainError(onchainErr);
          try {
            getRepos().apiKeys.recordOnchainFailure(record.id, code);
          } catch {
            // Non-fatal: DB write failure doesn't block HTTP response
          }
          req.log?.warn(
            { keyId: record.id, code },
            "ERC-8004 on-chain identity write failed — will retry",
          );
          auditService.log({
            eventType: "auth.onchain_identity_failed",
            actor: operatorId,
            resourceType: "api_key",
            resourceId: record.id,
            action: "create",
            metadata: { code },
            ip: req.ip,
            userAgent: req.headers["user-agent"],
          });
        }
      }

      return reply.status(201).send({
        api_key: rawKey,
        key_id: record.id,
        operator_id: operatorId,
        scopes: JSON.parse(record.scopes),
        rate_limit: record.rateLimit,
        expires_at: record.expiresAt,
        created_at: record.createdAt,
        warning: "Save this API key now — it will not be shown again.",
        trace_id,
        ed25519: ed25519Response,
        // Provisioning never generates or assigns an operator wallet.
        operator_wallet: { source: "none" },
        usage: {
          header: `Authorization: Bearer ${rawKey}`,
          trace_header: `x-pcc-trace-id: ${trace_id ?? "<trace_id>"}`,
          example: `curl -H "Authorization: Bearer ${rawKey}" -H "x-pcc-trace-id: ${trace_id ?? "<trace_id>"}" ${req.protocol}://${req.hostname}/api/capabilities/types`,
          trace_hint:
            "Echo `x-pcc-trace-id` on every subsequent request so PCC can correlate your onboarding journey. Quote it when filing `pcc_report` feedback.",
        },
        onchain: onchainAttempted
          ? onchainResult
            ? { status: "written", ...onchainResult }
            : { status: "pending", registryAddress: getIdentityRegistryAddress() }
          : { status: "disabled" },
      });
    } catch (err: unknown) {
      const code = classifyProvisionError(err);
      if (code === "too_many_keys") {
        return reply.status(429).send({
          error: "too_many_keys", message: "Maximum 5 active API keys per operator",
        });
      }
      if (code === "invalid_public_key") {
        return reply.status(400).send({
          error: "invalid_public_key",
          message: "publicKey must be a 32-byte Ed25519 public key (64 hex chars, optional 0x prefix)",
        });
      }
      if (code === "provision_in_progress") {
        return reply.status(500).send({
          error: "provision_failed", message: "Key provisioning in progress — try again in a moment",
        });
      }
      return reply.status(500).send({ error: "provision_failed", message: "Failed to provision key" });
    }
  }

async (req, reply) => {
      const { jobId } = req.params;
      const gate = gateJobRead(req, jobId);
      if (!gate.ok && gate.kind !== "not_found") return refuseJobRead(reply, gate);
      // A job the caller may not read gets what a job with no telemetry gets.
      // The job's own events, each judged as sent by the record filter too: an event that also
      // names a job the caller may not read is left out (review r3 of #403, HIGH).
      const filter = jobRecordFilterOf(req);
      if (!filter.ok) return refuseJobRead(reply, filter);
      const timeline = gate.ok ? keepAsSent(pipelineTelemetry.getTimeline(jobId), filter.keep) : [];
      return { jobId, timeline, phases: PIPELINE_PHASES };
    }

async (req, reply) => {
    // Restrict to operators with API keys (HIGH-04 fix — prevents arbitrary telemetry injection)
    const apiKeyId = (req as any).apiKeyId;
    const operatorId = (req as any).operatorId;
    if (!apiKeyId || !operatorId) {
      return reply.code(403).send({ error: "forbidden", message: "Telemetry emit requires operator API key authentication" });
    }

    const { jobId, phase, status, duration_ms, metadata, level, source } = req.body;

    if (!jobId || !phase || !status) {
      return reply.code(400).send({ error: "jobId, phase, status are required" });
    }
    if (!PIPELINE_PHASES.includes(phase) || !TELEMETRY_STATUSES.includes(status)) {
      return reply.code(400).send({ error: "invalid_telemetry_phase_or_status" });
    }

    // Sanitize metadata to prevent prompt injection in telemetry (AI-02 fix)
    const sanitizedMetadata = metadata ? sanitizeTelemetryMetadata(metadata) : undefined;

    const event = pipelineTelemetry.emit(jobId, phase, status, {
      duration_ms,
      metadata: sanitizedMetadata,
      level,
      source,
    });

    logger.info(`Telemetry event emitted: ${phase} → ${status}`, {
      source: source ?? "api",
      jobId,
      metadata: { phase, status, duration_ms },
    });

    return { event };
  }

async (req) => {
      const body = req.body as { proofId?: string; merkleRoot?: string; treeDepth?: number };

      // Anchor a Merkle root directly
      if (body.merkleRoot) {
        const depth = body.treeDepth ?? 0;
        try {
          const anchor = await starknetService.anchorMerkleRoot(body.merkleRoot, depth);
          trackServerEvent("zk_proof_anchored", {
            type: "merkle_root",
            merkleRoot: body.merkleRoot,
            txHash: anchor.txHash,
            mock: starknetService.isMock(),
          }, (req as any).operatorId);
          auditService.log({
            eventType: "zk.proof_anchored",
            actor: (req as any).operatorId ?? (req as any).apiKeyId,
            resourceType: "zk_anchor",
            resourceId: anchor.txHash,
            action: "anchor",
            metadata: { type: "merkle_root", merkleRoot: body.merkleRoot, depth, mock: starknetService.isMock() },
            ip: req.ip,
            userAgent: req.headers["user-agent"],
          });
          return { anchor, mode: starknetService.isMock() ? "mock" : "real" };
        } catch (err) {
          return { error: "anchor_failed", message: (err as Error).message };
        }
      }

      // Anchor an existing proof by ID
      if (!body.proofId) {
        return { error: "missing_params", message: "Provide proofId or merkleRoot" };
      }

      const dbProof = getRepos().encryption.findProofById(body.proofId);
      if (!dbProof) return { error: "proof_not_found" };

      const proof: ZKProof = {
        id: dbProof.id,
        proofType: dbProof.proofType as ZKProof["proofType"],
        commitmentId: dbProof.commitmentId,
        publicInputs: dbProof.publicInputs,
        proof: dbProof.proof,
        verificationKey: dbProof.verificationKey,
        verified: dbProof.verified,
        generatedAt: dbProof.generatedAt,
      };

      try {
        const anchor = await starknetService.anchorProof(proof);
        trackServerEvent("zk_proof_anchored", {
          type: "proof",
          proofId: body.proofId,
          txHash: anchor.txHash,
          mock: starknetService.isMock(),
        }, (req as any).operatorId);
        auditService.log({
          eventType: "zk.proof_anchored",
          actor: (req as any).operatorId ?? (req as any).apiKeyId,
          resourceType: "zk_anchor",
          resourceId: anchor.txHash,
          action: "anchor",
          metadata: { type: "proof", proofId: body.proofId, mock: starknetService.isMock() },
          ip: req.ip,
          userAgent: req.headers["user-agent"],
        });
        return { anchor, mode: starknetService.isMock() ? "mock" : "real" };
      } catch (err) {
        return { error: "anchor_failed", message: (err as Error).message };
      }
    }

(e: AppEvent) => {
    // Span name follows the existing facade convention: "<sponsor>.<kind>"
    // so traces group naturally by integration in the UI.
    const span = tracer.startSpan(`${e.sponsor}.${e.kind}`, {
      startTime: e.t,
      attributes: {
        "event.kind": e.kind,
        "event.sponsor": e.sponsor,
        "event.level": e.level ?? "info",
        ...(e.session_id ? { "event.session_id": e.session_id } : {}),
        ...(e.duration_ms !== undefined ? { "event.duration_ms": e.duration_ms } : {}),
        // Text lands as a span attribute rather than a span event so that
        // OTel exporters (Honeycomb, Tempo, etc.) which index attributes
        // can search on it. Already redacted by the bus per T1.6.
        "event.text": e.text.length > 1024 ? `${e.text.slice(0, 1021)}...` : e.text,
      },
    });
    if (statusForLevel(e.level) === "ERROR") {
      // recordException accepts any thrown-shape; we synthesize a minimal
      // error so tracing UIs render an error chip without us needing to
      // attach the raw payload (which may be large or sensitive).
      span.recordException({ name: `${e.sponsor}.${e.kind}`, message: e.text });
      span.setStatus({ code: 2, message: e.text });
    }
    // End immediately — events are already-completed milestones. If a
    // future iteration wants to model a "begin → end" pair as one parent
    // span, that's the `tracked()` helper's job, not this bridge's.
    span.end(e.duration_ms ? e.t + e.duration_ms : e.t);
  }

posthog.identify({
      distinctId: safeServerEventDistinctId(distinctId),
      properties: {
        ...safeServerEventProperties(properties),
        kind: "agent_journey",
        source: "gateway",
        environment: analyticsEnvironment(),
      },
    })

posthog.capture({
      distinctId: consumeServerEventDistinctId(distinctId),
      event: logSafeId(event),
      properties: {
        ...safeServerEventProperties(properties, event),
        source: "gateway",
        environment: analyticsEnvironment(),
      },
    })
